import atexit
import datetime
import os
import re
import sys
import time
import traceback

import mysql.connector
import pytz

from icputils import config, database
from logger import logger

logger = logger.setup_logger()

TIME_START = time.time()
TIME_STAMP = time.time()
DEBUG = False


def get_runtime():
    try:
        now = time.time()
        runtime = now - TIME_START
        return runtime
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return None


def get_epoch_timestamp():
    try:
        epoch_time = int(time.time())
        return epoch_time
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return None


# Function to get the weekly timestamps:
def get_timestamps_weekly():
    try:
        today = datetime.date.today()
        end = today + datetime.timedelta(hours=8)
        start = today - datetime.timedelta(days=7) + datetime.timedelta(hours=8)
        epoch_start = int(datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC).timestamp())
        tsdb_epoch_start = int((datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC) + datetime.timedelta(
            hours=8)).timestamp())
        tsdb_start_date = (datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC) + datetime.timedelta(
            hours=8)).strftime("%Y-%m-%dT%H:%M:%SZ")
        epoch_end = int(datetime.datetime(end.year, end.month, end.day, tzinfo=pytz.UTC).timestamp())
        tsdb_epoch_end = int((datetime.datetime.utcfromtimestamp(epoch_end - 1) + datetime.timedelta(hours=8)).timestamp())
        tsdb_end_date = (datetime.datetime.utcfromtimestamp(epoch_end - 1) + datetime.timedelta(hours=8)).strftime(
            '%Y-%m-%dT%H:%M:%SZ')
        yesterday = today - datetime.timedelta(days=1)
        settings = {
            'epoch_start': tsdb_epoch_start,
            'epoch_end': tsdb_epoch_end,
            'today': today,
            'entry_date': yesterday.strftime("%Y-%m-%d"),
            'timestamp': datetime.datetime.now(),
            'range': [tsdb_epoch_start, tsdb_epoch_end],
            'icp_start_date': datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC).strftime("%Y-%m-%d"),
            'icp_end_date': datetime.datetime.utcfromtimestamp(epoch_end - 1).strftime('%Y-%m-%d'),
        }
        return tsdb_start_date, tsdb_end_date, settings
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return None, None, None


# Function to get the daily timestamps:
def get_timestamps_daily():
    try:
        today = datetime.date.today()
        end = today + datetime.timedelta(hours=8)
        start = today - datetime.timedelta(days=1) + datetime.timedelta(hours=8)
        epoch_start = int(datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC).timestamp())
        tsdb_epoch_start = int((datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC) + datetime.timedelta(
            hours=8)).timestamp())
        tsdb_start_date = (datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC) + datetime.timedelta(
            hours=8)).strftime("%Y-%m-%dT%H:%M:%SZ")
        epoch_end = int(datetime.datetime(end.year, end.month, end.day, tzinfo=pytz.UTC).timestamp())
        tsdb_epoch_end = int((datetime.datetime.utcfromtimestamp(epoch_end - 1) + datetime.timedelta(hours=8)).timestamp())
        tsdb_end_date = (datetime.datetime.utcfromtimestamp(epoch_end - 1) + datetime.timedelta(hours=8)).strftime(
            '%Y-%m-%dT%H:%M:%SZ')
        yesterday = today - datetime.timedelta(days=1)
        settings = {
            'epoch_start': tsdb_epoch_start,
            'epoch_end': tsdb_epoch_end,
            'today': today,
            'entry_date': yesterday.strftime("%Y-%m-%d"),
            'timestamp': datetime.datetime.now(),
            'range': [tsdb_epoch_start, tsdb_epoch_end],
            'icp_start_date': datetime.datetime(start.year, start.month, start.day, tzinfo=pytz.UTC).strftime("%Y-%m-%d"),
            'icp_end_date': datetime.datetime.utcfromtimestamp(epoch_end - 1).strftime('%Y-%m-%d'),
        }
        return tsdb_start_date, tsdb_end_date, settings
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return None, None, None


def clean_text(text):
    try:
        if text:
            return re.sub(config.r_badchar, '', text)
        else:
            return ''
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return ''


def format_interface(interface, logical=True):
    try:
        interface = clean_text(interface).lower().strip()
        interface = interface.replace('tengigabitethernet', 'te').replace('tengige', 'te') \
            .replace('gigabitethernet', 'gi').replace('hundredgige', 'hu').replace('fastethernet', 'fa') \
            .replace('port-channel', 'po') \
            .replace('bundle-ethernet', 'be').replace('bundle-ether', 'be').replace('link-aggregate', 'la') \
            .replace('ethernet', 'et').replace('gigabitet', 'gi')

        if logical is False and '.' in interface:
            interface = interface.split('.')[0]

        return interface

    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return None


def get_interface_info(interface):
    try:
        info = {
            'type': None
        }
        if '.' in interface:
            info['type'] = 'logical'
        elif interface.startswith(('ae', 'po', 'be')):
            info['type'] = 'bundle'
        else:
            info['type'] = 'physical'

        return info
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return {}


def format_interface_delog(interface):
    try:
        interface = format_interface(interface)
        if '.' in interface:
            interface = interface.split('.')[0]

        return interface
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return None


def get_hostname_info(hostname):
    try:
        valid = True
        hostname = clean_text(hostname).lower().strip().replace('.comcast.net', '')
        site_name = ''
        cran_name = ''
        if hostname.count('.') == 3:
            hostname_segments = hostname.split('.')
            cran_name = hostname_segments[-1]
            site_name = '.'.join(hostname_segments[1:])

            if not config.r_prefix.search(hostname):
                valid = False
            else:
                for segment in hostname_segments:
                    if len(segment) == 0:
                        valid = False

        else:
            valid = False

        return {
            'valid': valid,
            'hostname': hostname,
            'site_name': site_name,
            'cran_name': cran_name
        }
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return {}


def format_hostname(hostname):
    try:
        hostname = clean_text(hostname).lower().strip()
        if hostname.endswith('.comcast.net'):
            hostname = hostname.replace('.comcast.net', '')

        return hostname
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return None


def get_site_info(site_name):
    try:
        valid = True
        site_name = clean_text(site_name).lower().strip().replace('.comcast.net', '')
        cran_name = ''
        if site_name.count('.') == 2:
            cran_name = site_name.split('.')[-1]

        else:
            valid = False

        return {
            'valid': valid,
            'site_name': site_name,
            'cran_name': cran_name
        }
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return {}


def cluster_workload(work_list, cluster_index=None, cluster_total=None):
    try:
        cluster = get_cluster_info()
        if cluster_index is None:
            cluster_index = cluster['index']
        if cluster_total is None:
            cluster_total = cluster['total']

        i = cluster_index
        while i < len(work_list):
            yield work_list[i]
            i += cluster_total
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")


def get_cluster_info():
    try:
        return {
            'index': int(os.environ.get('CLUSTER_INDEX', 0)),
            'total': int(os.environ.get('CLUSTER_TOTAL', 1)),
        }
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")
        return {}


def update_stamp(_id=None):
    try:
        cnx, cursor = database.mysql_con('matrix_db')
        run_time = int(get_runtime())
        file_path = os.path.abspath(sys.argv[0])
        if _id != None:
            cursor.execute("UPDATE matrix.script_stamp SET stamp=NOW(),run_time=%s,script_name=%s WHERE id=%s", (run_time, file_path, _id))
            update_script_history(cursor, _id, run_time)
        else:
            file_name = os.path.basename(sys.argv[0])
            cursor.execute("SELECT id, threshold_run_time FROM matrix.script_stamp WHERE file_name = %s", (file_name,))
            if cursor.rowcount == 1:
                row = cursor.fetchone()
                _id = row['id']
                threshold_run_time = row['threshold_run_time']
                if threshold_run_time:
                    cursor.execute("UPDATE matrix.script_stamp SET stamp=NOW(),run_time=%s,script_name=%s WHERE id=%s",
                                (run_time, file_path, _id))
                else:
                    new_th_rt = run_time * 0.2 # run time  + 20% of run time
                    cursor.execute("UPDATE matrix.script_stamp SET stamp=NOW(),run_time=%s,script_name=%s,threshold_run_time=%s WHERE id=%s",
                                (run_time, file_path, new_th_rt, _id))
                    update_script_history(cursor, _id, run_time)
            else:
                cursor.execute("INSERT INTO matrix.script_stamp (file_name,stamp,run_time,active,script_name) VALUES (%s,NOW(),%s,0,%s)",
                               (file_name, run_time, file_path))
                last_inserted_id = cursor.lastrowid
                update_script_history(cursor, last_inserted_id, run_time)
        logger.debug("Closed database: matrix_db connection")
        cnx.close()
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")


def update_script_history(cursor, script_id, run_time):
    try:
        cursor.execute("INSERT INTO matrix.scripts_history (script_id, stamp, run_time) VALUES (%s, NOW(), %s)", (script_id, run_time))
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")


def check_connection(cnx, db, dictionary=True):
    try:
        cnx.ping(
            reconnect=True,
            attempts=3,
            delay=5,
        )
        if dictionary:
            cursor = cnx.cursor(buffered=True, dictionary=True)
        else:
            cursor = cnx.cursor(buffered=True)
    except mysql.connector.InterfaceError as err:
        logger.exception(f"Exception: {err}, {traceback.format_exc()}")
        (cnx, cursor) = database.mysql_con(db)
    return (cnx, cursor)


############################
# Rebinding Exception Hooks
class ExitHooks(object):
    def __init__(self):
        self.exit_code = None
        self.exception = None

    def hook(self):
        self._orig_exit = sys.exit
        self._orig_exc = sys.excepthook
        sys.exit = self.exit
        sys.excepthook = self.exc_handler

    def exit(self, code=0):
        self.exit_code = code
        self._orig_exit(code)

    def exc_handler(self, exc_type, exc, trace):
        self.exception = exc
        self._orig_exc(exc_type, exc, trace)

    def isSuccess(self):
        if (self.exit_code == None or self.exit_code == 0) and self.exception == None:
            return True
        else:
            return False


hooks = ExitHooks()
hooks.hook()


############################
# At Exit reading new hooks

def exit_stamp():
    try:
        if hooks.isSuccess():
            update_stamp()
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")


def start():
    logger.debug("Started icputils")


atexit.register(exit_stamp)

