    @staticmethod
    def start_thread(function_name, data_list, max_workers=20):
        final_data = []
        try:
            with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
                results = [executor.submit(function_name, data_dict) for data_dict in data_list]
                concurrent.futures.wait(results)
                for future in results:
                    final_data.extend(future.result())
        except Exception as e:
            logger.exception(f"Exception occurred in start_thread: {e}, {traceback.format_exc()}")
        return final_data

    def get_model_id(self, model_name, model_nick_name=None):
        model_id = None
        table_name = f"{self.schema_name}.model"
        try:
            if not self.model_dict:
                try:
                    query = f"select modelId, modelName from {table_name};"
                    result = self.run_query(query, 'SELECT')
                    for data in result:
                        if data.get('modelName'):
                            self.model_dict[str(data.get('modelName')).strip().lower()] = data.get('modelId')
                except Exception as e:
                    logger.exception(f"Exception occurred in get_model: {e}, {traceback.format_exc()}")
            if model_name:
                model_name = IomUtils.get_converted_value(model_name, 'str', strip_pattern=" \t\n\r\0\x0B.,-\"'#;=*", first_characters=50)
                if model_name:
                    model_name = model_name.replace('EQUAL', '') if search(r'EQUAL$', model_name) else model_name
                    model_name = sub(r'[\'"]', '', model_name)
                    model_name = original_model_name = (sub(r'[^\x20-\x7E]', '', model_name)).strip()
                    model_id = self.model_dict.get(model_name.lower()) if model_name else None
                    if not model_id and model_name:
                        if model_nick_name:
                            model_nick_name = IomUtils.get_converted_value(model_nick_name, 'str', strip_pattern=" \t\n\r\0\x0B.,-\"'#;=*")
                            if model_nick_name:
