    def get_shipped_discrepancies(self, retry=1, hours=1):
        self.get_db_and_server_time()
        table_name = "bom_database.shipped_discrepancies"
        shipped_discrepancies = []
        try:
            query = f'SELECT row_data_json FROM {table_name} WHERE DATE(created_at) = CURDATE();'
            result = self.run_query(query, 'SELECT')
            if result:
                logger.debug(f"Data is found in {table_name} table for today, script will execute now")
                result = result[0].get('row_data_json')
                result = loads(result) if result else []
                for data in result:
                    asset_ids = data['assetId'].split(',')
                    for asset_id in asset_ids:
                        shipped_discrepancies.append({data['poNumberPermanent']: asset_id})
            else:
                logger.debug(f"Data is not found in {table_name} table, retry: {retry}, hours: {hours}")
                if retry % 12 == 0:
                    # Check for every 1 hour for next 12 hours.
                    if hours == 12:
                        return shipped_discrepancies
                    hours += 1
                # Sleep for 5 minutes.
                sleep(300)
                return self.get_shipped_discrepancies(retry + 1, hours)
        except Exception as e:
            logger.exception(f"Exception occurred in get_shipped_discrepancies: {e}, {traceback.format_exc()}")
        return shipped_discrepancies

