    @staticmethod
    def get_numeric_value(value, decimal_places=None, original=None, absolute=None, value_range=None, first_characters= None):
        result = None
        try:
            if value:
                is_number = False
                value = str(value)
                value = value.replace(',', '')
                int_pattern = r'^-?\d+$'
                float_pattern = r'^-?\d+\.\d*$'
                if match(int_pattern, value):
                    is_number = True
                    result = int(value)
                elif match(float_pattern, value):
                    is_number = True
                    if decimal_places:
                        value = f"{float(value):.{decimal_places}f}"
                        result = float(value)
                    elif original:
                        result = float(value)
                    else:
                        result = int(float(value))
                if is_number:
                    if absolute:
                        result = abs(result)
                    if value_range == "mediumint":
                        result = result if result and (0 <= result <= 16777215) else None
                    elif value_range == "int":
                        result = result if result and (0 <= result <= 4294967295) else None
                    elif value_range == "tinyint":
                        result = result if result and (0 <= result <= 255) else None
                    elif value_range == "bigint":
                        result = result if result and (0 <= result <= 18446744073709551615) else None
                    elif value_range == "signed int":
                        result = result if result and (-2147483648 <= result <= 2147483647) else None
        except Exception as e:
            logger.exception(f"Exception occurred in for value: {value} in get_numeric_value: {e}, {traceback.format_exc()}")
        return result

    @staticmethod
    def get_converted_value(value, value_type='str', pattern=None, strip_pattern=None, first_characters=None, value_range=None):
        try:
            if value:
                value = str(value)
                value = sub(r'[^\x20-\x7E]', '', value).strip()
                if strip_pattern:
                    value = value.strip(strip_pattern)
                if pattern:
                    value = sub(pattern, '', value)
                if first_characters:
                    value = value[:first_characters]
                if value_type == 'str':
                    value = str(value) if value else None
                elif value_type == 'int':
                    value = int(value) if value else None
                    if value_range == "mediumint":
                        value = value if value and (0 <= value <= 16777215) else None
                    elif value_range == "int":
                        value = value if value and (0 <= value <= 4294967295) else None
                    elif value_range == "tinyint":
                        value = value if value and (0 <= value <= 255) else None
                    elif value_range == "bigint":
                        value = value if value and (0 <= value <= 18446744073709551615) else None
                    elif value_range == "signed int":
                        value = value if value and (-2147483648 <= value <= 2147483647) else None
            else:
                value = None
        except Exception as e:
            logger.exception(f"Exception occurred for value: {value} in get_converted_value: {e}, {traceback.format_exc()}")
            value = None
        return value

    @staticmethod
    def count_rows_in_csv(file_path):
        row_count = 0
        file_found = False
        try:
            if path.isfile(file_path):
                file_found = True
                with open(file_path, 'r') as csv_file:
                    reader = csv.reader(csv_file)
                    row_count = sum(1 for _ in reader)
                    logger.debug(f"Total records in the file: {file_path} is {row_count}")
            else:
                logger.debug(f"File is not found at path: {file_path}")
        except Exception as e:
            logger.exception(f"Exception occurred in count_rows_in_csv: {e}, {traceback.format_exc()}")
        return file_found, row_count

    def get_project_list(self):
        results = []
        try:
            query = f"""
            SELECT 
                GROUP_CONCAT(DISTINCT project_number
                    SEPARATOR '|') AS project_num
            FROM
                {self.schema_name}.projects
                where status = 1
            GROUP BY subteam
            ORDER BY CASE
                WHEN subteam LIKE 'CRAN%' THEN 'a'
                WHEN subteam = 'TRANSPORT' THEN 'b'
                WHEN subteam = 'ENTERPRISE' THEN 'c'
                WHEN subteam = 'BACKBONE' THEN 'd'
                WHEN subteam IS NULL THEN 'z'
                ELSE subteam
            END
            """
            result = self.run_query(query, "SELECT")
            for row in result:
                if("|" in row.get('project_num')):
                    project_num = [{'project_num': item} for item in row.get('project_num').split('|')]
                    results.extend(project_num)
                else:
                    results.append(row)

            query = f"""
            SELECT 
                GROUP_CONCAT(DISTINCT r12_project
                    SEPARATOR '|') AS project_num
            FROM
                bom_database.bu_div_projects
            WHERE
                status = 1
                    AND YEAR IN (YEAR(CURDATE()) , YEAR(CURDATE()) - 1)
            GROUP BY lob
            """
            result = self.run_query(query, "SELECT")
            for row in result:
                if("|" in row.get('project_num')):
                    project_num = [{'project_num': item} for item in row.get('project_num').split('|')]
                    results.extend(project_num)
                else:
                    results.append(row)
        except Exception as e:
            logger.exception(f"Exception occurred in get_project_list: {e}, {traceback.format_exc()}") 
        return results

    def get_date_range(self, from_days, to_days):
        from_date = to_date = None
        try:
            query = f"""
            SELECT 
                DATE_FORMAT(CURDATE() - INTERVAL {from_days} DAY, '%Y-%m-%d') AS from_date,
                DATE_FORMAT(CURDATE() + INTERVAL {to_days} DAY, '%Y-%m-%d') AS to_date
            """
            result = self.run_query(query, "SELECT")
            for row in result:
                from_date = datetime.strptime(row.get('from_date'), '%Y-%m-%d')
                to_date = datetime.strptime(row.get('to_date'), '%Y-%m-%d')
        except Exception as e:
            logger.exception(f"Exception occurred in get_date_range: {e}, {traceback.format_exc()}")
        return from_date, to_date

    def get_pagination_result(self, query, result_list=None, offset=0, limit=100000):
        try:
            result_list = result_list if result_list else []
            result = self.run_query(f"{query} LIMIT {offset}, {limit};", "SELECT")
            if result:
                result_list.extend(result)
                if len(result) == limit:
                    self.get_pagination_result(query, result_list, offset + limit)
                    offset += limit
            logger.debug(f"Pagination count: {len(result_list)}")
        except Exception as e:
            logger.exception(f"Exception occurred in get_pagination_result: {e}, {traceback.format_exc()}")
        return result_list

    def update_query_pagination(self, query, record_ids, message, limit=1000):
        status = False
        try:
            result_list = []
            count = int(ceil(len(record_ids) / limit))
            for start_index in range(0, len(record_ids), limit):
                end_index = start_index + limit
                chunk = record_ids[start_index:end_index]
                ids = ','.join([f'"{str(item)}"' for item in chunk])
                result = self.run_query(query % ids, "UPDATE")
                if result:
                    logger.debug(f"{count} - Success - {message}")
                else:
                    logger.debug(f"{count} - Fail - {message}")
                count -= 1
                result_list.append(result)
            result_set = list(set(result_list))
            if len(result_set) == 1 and result_set[0]:
                status = True
            else:
                logger.debug("Update is not successful")
        except Exception as e:
            logger.exception(f"Exception occurred in update_query_pagination: {e}, {traceback.format_exc()}")
        return status

    def select_and_update(self, select_query, update_query, insert_result, comment):
        status = False
        try:
            results = self.get_pagination_result(select_query)
            ids = [result.get('id') for result in results]
            logger.debug(f"Select query result: {len(ids)}")
            if ids:
                status = self.update_query_pagination(update_query, ids, comment)
            else:
                insert_result[f"{comment} message"] = "No data found to update"
        except Exception as e:
            logger.exception(f"Exception occurred in select_and_update: {e}, {traceback.format_exc()}")
        insert_result[comment] = status
        return insert_result

    def get_users_dict(self):
        table_name = f"{self.schema_name}.users"
        try:
            if not self.users_dict:
                try:
                    query = f"select `id`, email_address from {table_name};"
                    result = self.run_query(query, 'SELECT')
                    for data in result:
                        if data.get('email_address'):
                            self.users_dict[str(data.get('email_address')).lower().strip()] = data.get('id')
                except Exception as e:
                    logger.exception(f"Exception occurred in get_users: {e}, {traceback.format_exc()}")
        except Exception as e:
            logger.exception(f"Exception occurred in get_users_dict: {e}, {traceback.format_exc()}")

    def get_users_id(self, email_address, full_name):
        table_name = f"{self.schema_name}.users"
        users_id = None
        try:
            if email_address:
                email_address = sub(r"['\"=]", '', email_address)
                email_address = (sub(r'[^\x20-\x7E]', '', email_address)).strip().lower() if email_address else None
                if match(r'[\w\.-]+@[\w\.-]+\.\w{2,}', email_address):
                    users_id = self.users_dict.get(email_address) if email_address else None
                    if not users_id and email_address:
                        query = f'select `id` from {table_name} where lower(trim(email_address)) = "{email_address}";'
                        result = self.run_query(query, 'SELECT')
                        if result:
                            users_id = result[0].get('id')
                        if not users_id:
                            full_name = sub(r"[\t\n\r.,-]", ' ', full_name) if full_name else None
                            full_name = (sub(r'[^\x20-\x7E]', '', full_name)).strip() if full_name else None
                            query = f'insert into {table_name} (email_address, full_name) values ("{email_address}", "{full_name}");'
                            users_id = self.run_query(query, 'INSERT')
                            if users_id:
                                self.users_dict[email_address] = users_id
        except Exception as e:
            logger.exception(f"Exception occurred in get_users_id: {e}, {traceback.format_exc()}")
        return users_id

    def get_supplier_dict(self):
        table_name = f"{self.schema_name}.supplier"
        try:
            if not self.supplier_dict:
                try:
                    query = f"select `id`, supplier_name from {table_name};"
                    result = self.run_query(query, 'SELECT')
                    for data in result:
                        if data.get('supplier_name'):
                            self.supplier_dict[str(data.get('supplier_name')).lower().strip()] = data.get('id')
                except Exception as e:
                    logger.exception(f"Exception occurred in get_supplier: {e}, {traceback.format_exc()}")
        except Exception as e:
            logger.exception(f"Exception occurred in get_supplier_dict: {e}, {traceback.format_exc()}")

    def get_supplier_id(self, supplier_name):
        table_name = f"{self.schema_name}.supplier"
        supplier_id = None
        try:
            if supplier_name:
                supplier_name = original_supplier_name = IomUtils.get_converted_value(supplier_name)
                supplier_name = supplier_name.strip().lower() if supplier_name else None
                supplier_id = self.supplier_dict.get(supplier_name) if supplier_name else None

                if not supplier_id and supplier_name:
                    query = f'select `id` from {table_name} where lower(trim(supplier_name)) = "{supplier_name}";'
                    result = self.run_query(query, 'SELECT')
                    if result:
                        supplier_id = result[0].get('id')
                    if not supplier_id:
                        query = f'insert into {table_name} (supplier_name) values ("{original_supplier_name}");'
                        supplier_id = self.run_query(query, 'INSERT')
                        if supplier_id:
                            self.supplier_dict[supplier_name] = supplier_id
        except Exception as e:
            logger.exception(f"Exception occurred in get_supplier_id: {e}, {traceback.format_exc()}")
        return supplier_id

    def check_log_record(self, table_name, retry_flag=False, retry=1, hours=1):
        self.get_db_and_server_time()
        status = False
        try:
            result = self.check_script_run(table_name)
            if result:
                status = True
                logger.debug(f"Record exist for table: {table_name}")
            elif retry_flag:
                message = f"Record doesn't exist for table: {table_name}"
                logger.debug(f"{message}, retry: {retry}, hour(s): {hours}")
                if retry % 12 == 0:
                    if hours == 12:
                        return False
                    hours += 1
                # Sleep for 5 minutes.
                sleep(300)
                return self.check_log_record(table_name, True, retry + 1, hours)
            else:
                logger.debug(f"Record doesn't exist for table: {table_name}")
        except Exception as e:
            logger.exception(f"Exception occurred in check_log_record: {e}, {traceback.format_exc()}")
        return status

    def get_config_value(self, key):
        value = {}
        try:
            query = f"SELECT `value` FROM bom_database.config WHERE `key` = '{key}';"
            result = self.run_query(query, 'SELECT')
            if result:
                value = loads(result[0].get('value')) if len(result) == 1 else {}
        except Exception as e:
            logger.exception(f"Exception occurred in key: {key} from get_config_value: {e}, {traceback.format_exc()}")
        return value

    def select_and_insert_data(self, table_name, insert_result, query=None, truncate=False, ignore=False, query_result=None, table_prefix=None):
        try:
            if query:
                query_result = self.get_pagination_result(query)
            table_name_log = f"{table_prefix}_{table_name}" if table_prefix else table_name
            if query_result:
                result, duplicate_count, unique_count = self.insert_data(query_result, table_name, truncate=truncate, ignore=ignore)
                if result:
                    logger.debug(f"{result} records inserted into {table_name_log} table")
                insert_result[f'{table_name_log}_duplicate_count'] = duplicate_count
                insert_result[f'{table_name_log}_unique_count'] = unique_count
            else:
                message = f"No records found to insert into {table_name_log} table"
                logger.debug(message)
                result = 0
                insert_result[f'{table_name_log}_message'] = message
            insert_result[f'{table_name_log}_total_records_inserted'] = result
        except Exception as e:
            logger.exception(f"Exception occurred in select_and_insert_data: {e}, {traceback.format_exc()}")
        return insert_result

    @staticmethod
    def insert_data_mongo(insert_list, collection, collection_name, limit=10000):
        insert_result = False
        try:
            count = int(ceil(len(insert_list) / limit))
            for start_index in range(0, len(insert_list), limit):
                end_index = start_index + limit
                chunk = insert_list[start_index:end_index]
                collection.insert_many(chunk)
                logger.debug(f"{count} - Inserted {len(chunk)} records into {collection_name}")
                count = count - 1
            insert_result = True
        except Exception as e:
            logger.exception(f"Exception occurred in insert_data_mongo: {e}, {traceback.format_exc()}")
        return insert_result

    @staticmethod
    def get_quarters_from_start_date(start_date_str):
        quarter_dates = []
        try:
            if start_date_str:
                start_flag = False

                start_date = datetime.strptime(start_date_str, "%Y-%m-%d").date()
                current_date = datetime.now().date()

                while start_date <= current_date:
                    quarter_start_month = ((start_date.month - 1) // 3) * 3 + 1

                    if not start_flag:
                        quarter_start = start_date
                        start_flag = True
                    else:
                        quarter_start = date(start_date.year, quarter_start_month, start_date.day)

                    last_day_of_month = calendar.monthrange(start_date.year, quarter_start_month + 2)[1]
                    quarter_end = date(start_date.year, quarter_start_month + 2, last_day_of_month)
                    quarter_end = min(quarter_end, current_date)

                    quarter_dates.append(
                        {
                            "quarter": f"{quarter_start.year}Q{((quarter_start.month - 1) // 3) + 1}",
                            "current_date": current_date.strftime("%Y-%m-%d"),
                            "start_date": quarter_start.strftime("%Y-%m-%d"),
                            "end_date": quarter_end.strftime("%Y-%m-%d")
                        })
                    start_date = quarter_end + timedelta(days=1)
        except Exception as e:
            logger.exception(f"Exception occurred in get_quarters_from_start_date: {e}, {traceback.format_exc()}")
        return quarter_dates

    @staticmethod
    def get_quarter_start_date(given_date):
        quarter_start_date = None
        try:
            given_date = datetime.strptime(given_date, "%Y-%m-%d").date()
            month = given_date.month
            year = given_date.year
            quarter_start_month = ((month - 1) // 3) * 3 + 1
            quarter_start_date = date(year, quarter_start_month, 1)
        except Exception as e:
            logger.exception(f"Exception occurred in get_quarter_start_date: {e}, {traceback.format_exc()}")
        return quarter_start_date

    """
    #fields = {'last_update': '2024-03-01 14:01:42', 'one_time_update': 1, 'run_counter': 4, 'one_time_update_time' : '2024-03-01 14:01:42'}
    """

    def update_script_stamp(self, script_id, execution, fields={}, allowedBuffTime=0, maxBuffAllowTime=0):
        execute = False
        try:
            updateFields = ''
            if fields:
                for dbField, dbValue in fields.items():
                    updateFields += f", {dbField} = '{dbValue}' "

            # Set the timezone to "America/New_York"
            eastern = pytz.timezone('America/New_York')
            currUSTime = datetime.now(eastern).replace(tzinfo=None)
            if execution == 'start':
                query = f"SELECT * from filemaker2.script_stamp_status WHERE script_id = {script_id};"
                current_status = self.run_query(query, "SELECT")
                logger.debug(f"Query result: {current_status[0]}")
                execute = True
                if current_status[0]['completion_status'] == 2:
                    execute = True
                if current_status[0]['completion_status'] != 1 and current_status[0]['completion_status'] != 2:
                    lastExeDateTime = current_status[0]['last_run']
                    lastRunPlusAllowedBuff = lastExeDateTime + timedelta(hours=allowedBuffTime)
                    lastRunPlusMaxBuff = lastExeDateTime + timedelta(hours=maxBuffAllowTime)

                    # Make lastRunPlusAllowedBuff timezone-aware by converting it to the "America/New_York" timezone
                    lastRunPlusAllowedBuff = lastRunPlusAllowedBuff.replace(tzinfo=None)

                    if (currUSTime > lastRunPlusAllowedBuff) and (currUSTime < lastRunPlusMaxBuff or maxBuffAllowTime == 0):
                        execute = True
                    else:
                        execute = False

                if execute == True:
                    query = f"UPDATE filemaker2.script_stamp_status SET completion_status = 0 WHERE script_id = {script_id};"
                    self.run_query(query, "UPDATE")

            if execution == 'complete':
                query = f"UPDATE filemaker2.script_stamp_status SET completion_status = 1, last_run = '{currUSTime}' {updateFields} WHERE script_id = {script_id};"
                self.run_query(query, "UPDATE")
                execute = True
            if execution == 'error':
                query = f"UPDATE filemaker2.script_stamp_status SET completion_status = 2, last_run = '{currUSTime}' {updateFields} WHERE script_id = {script_id};"
                self.run_query(query, "UPDATE")
                execute = True
        except Exception as e:
            logger.exception(f"Exception occurred in wo scheduler: {e}, {traceback.format_exc()}")
            execute = False
        return execute

    def get_config_status(self, key):
        status = False
        try:
            query = f"SELECT `status` FROM bom_database.config WHERE `key` = '{key}' AND `status` = '1';"
            result = self.run_query(query, 'SELECT')
            if result:
                status = True
        except Exception as e:
            print(f"Exception occurred in key: {key} from get_config_status: {e}, {traceback.format_exc()}")
        return status

