import json
import traceback

import requests

import icputils.config
import icputils.config
from icputils import util
from logger import logger

logger = logger.setup_logger()


class UnlockWoHandler:
    def __init__(self, iom_utils):
        self.iom_utils = iom_utils
        util.start()

    def fetch_wo_details(self, wo_number):
        try:
            wo = f"WO-{wo_number}"
            query = {"WOPrefix_Number": wo}
            response = requests.post(f"{icputils.config.env_configs.get('api_url')}/api/filemaker_api/api_work_orders", data=query, verify=False)
            current_step = None
            response = json.loads(response.text)
            if response:
                for rows in response.get('parsed_response', {}).get('fm_wo_bom_list', []):
                    current_step = rows.get('currentStep', '')
            return current_step, wo
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def unlock_wo(self, wo_number):
        try:
            current_step, wo = self.fetch_wo_details(wo_number)
            results = {}
            payload = {
                "Action": "SetField",
                "FieldName": "NetEngLock",
                "Value": "0",
                "WO": wo
            }

            if current_step == "Draft":
                results = requests.post(f"{icputils.config.env_configs.get('api_url')}/api/wo_automation/wo_lock_switch", data=payload, verify=False)
                self.process_response(results, wo_number)

            else:
                results[wo_number] = 'wo_status_not_in_draft'
                logger.debug(f"{wo_number} is not in draft mode")

            return results
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def process_response(self, response, wo_number):
        try:
            results = {}
            wo_success = {}
            wo_failure = {}

            response = json.loads(response.text)

            if response.get('response', {}).get('response').get('scriptError') == "1":
                results['error'] = 1
                results['neteng_lock'] = 0
            else:
                results['error'] = 0

                formatted_results = response.get('response', {}).get('response').get('data', [])
                logger.debug(formatted_results)
                if formatted_results:
                    for field_data in formatted_results:
                        single_field_data = field_data.get('fieldData', {})
                        if not single_field_data.get('NetEngLock') and single_field_data.get('CurrentStepCalc') == 'Draft':
                            wo_success[wo_number] = 'successfully_unlocked'
                            query = f"INSERT INTO cifa.fm_wo_lock (woNumber, lockStatus) values ('{wo_number}', '{single_field_data.get('NetEngLock')}')  ON DUPLICATE KEY UPDATE lockStatus = VALUES(lockStatus)"
                            self.iom_utils.run_query(query, "insert")
                        else:
                            wo_failure[wo_number] = 'something_went_wrong_not_able_to_unlock'
                            results['error'] = 1
                else:
                    results['error'] = 1

            results['success'] = wo_success
            if wo_failure:
                results['failure'] = wo_failure
            logger.debug(results)
            return results
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

