import traceback
from datetime import datetime

import requests

from icputils import util
from icputils.iom_utils import IomUtils
from logger import logger

logger = logger.setup_logger()


class FilemakerIssueScheduler:
    def __init__(self):
        self.iom_utils = IomUtils()
        self.filemaker_issue_scheduler()

    def filemaker_issue_scheduler(self):
        try:
            start_time = datetime.now()
            util.start()

            url = "https://networktools.comcast.net/bom/html/filemaker_issue_scheduler.php"
            payload = {}
            headers = {}

            response = requests.request("GET", url, headers=headers, data=payload, timeout=None)
            logger.debug(f"filemaker_issue_scheduler status_code: {response.status_code}")

            end_time = datetime.now()
            self.iom_utils.calculate_run_time(start_time, end_time, table="filemaker_issue_scheduler", comment="filemaker_issue_scheduler")
        except requests.exceptions.ReadTimeout as e:
            logger.debug(f"ReadTimeout exception occurred, but the script will run in background, {e}")
        except requests.RequestException as e:
            logger.debug(f"RequestException occurred, but the script will run in background, {e}")
        except Exception as e:
            logger.exception(f"Exception occurred in filemaker_issue_scheduler: {e}, {traceback.format_exc()}")


if __name__ == '__main__':
    FilemakerIssueScheduler()

