class ThreadedApiProcessor:
    def __init__(self, max_workers=5, timeout=30):
        self.max_workers = max_workers
        self.timeout = timeout
        self.results_queue = queue.Queue()

    def process_items(self, items, api_url, param_key='id'): 
        def make_api_call(item):
            try: 

                response = requests.post(api_url, data=item[1], timeout=None, verify=False)
                if response.status_code == 200:
                    result = {
                        "original_data": item,
                        "api_result": response.json(),
                        "status": "success",
                        "status_code": response.status_code
                    }
                else:
                    result = {
                        "original_data": item,
                        "api_result": None,
                        "status": "error",
                        "status_code": response.status_code,
                        "error": f"API returned status code {response.status_code}"
                    }

                self.results_queue.put(result)
                return result

            except Exception as e:
                print(str(e))
                error_result = {
                    "original_data": item,
                    "api_result": None,
                    "status": "error",
                    "error": str(e)
                }
                self.results_queue.put(error_result)
                return error_result

        while not self.results_queue.empty():
            self.results_queue.get()


        with ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            futures = [executor.submit(make_api_call, item) for item in items]

        results = []
        while not self.results_queue.empty():
            results.append(self.results_queue.get())

        return results

    def get_results(self):
        """Get all results from the results queue"""
        results = []
        while not self.results_queue.empty():
            results.append(self.results_queue.get())
        return results

