            query = f"SELECT * FROM matrix.script_stamp WHERE file_name = '{file_name}'"
            result = self.iom_utils.run_query(query, "SELECT")
            script_owner = ''
            script_id = ''
            if result:
                script_owner = result[0]['creator'] if result[0]['creator'] else ''
                script_id = result[0]['id'] if result[0]['id'] else ''
            try:

                ran = script().process()
                print("etrdsgtfdgfdgfdgfdg")
                print(ran)
                print("tyt666")
                self.results[script_name] = ran

                ran['script_name'] = file_name
                ran['description'] = result[0]['description'] if result[0]['id'] else ''
                ran['created_at'] = datetime.now()
                ran['class'] = script.__name__ if hasattr(script, '__name__') else f"Script_{i}"
                ran['script_owner'] = script_owner 
                ran['issue_raised'] = False
                self.results = ran
                if(ran.get('status') == "not completed"): 
                    self.results['script_owner'] = script_owner
