        self.execute_workflow_moves()

    def execute_workflow_moves(self):
        try:
            self.move_to_pending_hw_arrival()
            self.move_to_wh()
            self.move_to_wh_completed()
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def move_to_pending_hw_arrival(self):
        try:
            query = """
                SELECT w.workflow_id, w.type, pw.po_number FROM bom_database.de_proc_workflow w LEFT JOIN cifa.po_workflow pw ON w.workflow_id = pw.workflow_number WHERE w.status = 11 AND pw.po_number > 0 AND w.workflow_id NOT IN (SELECT DISTINCT pw.workflow_number FROM cifa.po_workflow pw JOIN bom_database.de_proc_workflow w ON w.workflow_id = pw.workflow_number LEFT JOIN cifa.preq_details pd ON pd.preq_number = pw.preq_number WHERE pw.po_number = 0 AND w.status = 11 AND pd.delete_flag = 0 AND pd.status != 'APPROVED') GROUP BY w.workflow_id
            """
            fetch = self.iom_utils.run_query(query, "SELECT")
            if fetch:
                for data in fetch:
                    workflow_id = data["workflow_id"]
                    self.update_workflow_and_notify(
                        workflow_id, "move_to_pending_hw_arrival", 59
                    )
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def update_workflow_status(self, workflow_id, status):
        try:
            query = f"UPDATE bom_database.de_proc_workflow SET status = {status}, update_time = NOW() WHERE workflow_id = {workflow_id}"
            self.iom_utils.run_query(query, "UPDATE")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def insert_workflow_log(self, workflow_id, status, type_val):
        try:
            query = f"INSERT INTO `bom_database`.`de_proc_workflow_log`(`workflow_id`, `update_time`, `status`, `user_id`, `type`) VALUES ({workflow_id}, CURRENT_TIMESTAMP, {status}, {self.user_id}, {type_val})"
            self.results = self.iom_utils.run_query(query, "INSERT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def get_workflow_info_for_completion(self):
        try:
            query = """SELECT workflow_id as workflow_number,type from bom_database.de_proc_workflow where status=62
            """
            return self.iom_utils.run_query(query, "SELECT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def get_po_items_info(self, workflow_number):
        try:
            query = f"""SELECT pi.po_number, fm.poNumber, fm.CIFANumber, IF(fm.totReceived, fm.totReceived, 0) as totReceived, totShipped, pi.quantity FROM cifa.po_items pi LEFT JOIN cifa.po_workflow pw ON pw.po_number = pi.po_number JOIN cifa.preq_details pd ON pd.preq_number = pw.preq_number and pd.delete_flag = 0 and pd.status = 'APPROVED' LEFT JOIN cifa.fm_po_line fm ON fm.poNumber = pi.po_number AND fm.CIFANumber = pi.cifa_item_number WHERE pw.workflow_number ={workflow_number} and pd.preq_number is not null
            """
            return self.iom_utils.run_query(query, "SELECT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def move_to_wh_completed(self):
        try:
            fetch = self.get_workflow_info_for_completion()
            if fetch:
                for data in fetch:
                    workflow_number = data["workflow_number"]
                    po_items_info = self.get_po_items_info(workflow_number)
                    if po_items_info and any(
                            item["totShipped"] is not None
                            and item["totShipped"] < item["totReceived"]
                            for item in po_items_info
                    ):
                        self.update_workflow_and_notify(
                            workflow_number, "move_wh_completed", 63
                        )
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def update_workflow_and_notify(self, workflow_number, type_val, status):
        try:
            self.update_workflow_status(workflow_number, status)
            self.execute_script_and_notify(workflow_number)
            self.send_email_notification(workflow_number, type_val)
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def execute_script_and_notify(self, workflow_number):
        try:
            insertWfTemp(str(workflow_number))
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def get_workflow_info_for_wh(self, workflow_number):
        try:
            query = f"""
                SELECT pw.workflow_number, GROUP_CONCAT(pw.po_number), w.type FROM cifa.po_workflow pw JOIN bom_database.de_proc_workflow w ON w.workflow_id = pw.workflow_number WHERE pw.workflow_number NOT IN (SELECT DISTINCT pw.workflow_number FROM cifa.po_workflow pw LEFT JOIN cifa.preq_details pd ON pd.preq_number = pw.preq_number AND pd.delete_flag = 1 WHERE pw.po_number = 0 AND pd.preq_number IS NULL) AND w.status = 59 GROUP BY pw.workflow_number
            """
            return self.iom_utils.run_query(query, "SELECT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")
            return []

    def move_to_wh(self):
        try:
            query = """SELECT pw.workflow_number, GROUP_CONCAT(pw.po_number), w.type FROM cifa.po_workflow pw JOIN bom_database.de_proc_workflow w ON w.workflow_id = pw.workflow_number WHERE pw.workflow_number NOT IN (SELECT DISTINCT pw.workflow_number FROM cifa.po_workflow pw LEFT JOIN cifa.preq_details pd ON pd.preq_number = pw.preq_number and pd.delete_flag = 1 WHERE pw.po_number = 0 and pd.preq_number is NULL) AND w.status = 59 GROUP BY pw.workflow_number
            """
            fetch = self.iom_utils.run_query(query, "SELECT")
            if fetch:
                for data in fetch:
                    workflow_number = data["workflow_number"]
                    res = self.get_po_items_info(workflow_number)
                    if res and any(item["totReceived"] < item["quantity"] for item in res):
                        self.update_workflow_and_notify(
                            workflow_number, "move_to_wh_fulfillment", 62
                        )
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def send_email_notification(self, workflow_id, action):
        try:
            de_to = []
            de_acknowledgers = []

            if workflow_id and workflow_id:
                query = f"""SELECT u.user_email, cws.workflow_email FROM bom_database.users u JOIN  bom_database.de_proc_workflow_log bdl ON bdl.user_id = u.user_id JOIN cifa.po_workflow cpw ON cpw.workflow_number = bdl.workflow_id LEFT JOIN cifa.workflow_stakeholder cws ON cws.workflow_id = cpw.workflow_number WHERE cpw.workflow_number = {workflow_id}
                """
                result = self.iom_utils.run_query(query, "SELECT")
                if result:
                    for emailid in result:
                        de_acknowledgers.extend(
                            [emailid["user_email"], emailid["workflow_email"]]
                        )

                # -----TODO fix with get_input from common API----#
                query = "SELECT u.user_email, ut.users_teams_team from users u JOIN users_teams ut ON ut.users_teams_user = u.user_id WHERE IFNULL(u.user_ad_disable,0 ) = 0 AND  ut.users_teams_proc_ph2_cnss = 1 GROUP BY u.user_id"
                result = self.iom_utils.run_query(query, "SELECT")

                if result and "user_email" in result[0]:
                    de_to.extend([emailid["user_email"] for emailid in result])

                # de_acknowledgers.append('Warren_Thurston@cable.comcast.com')

                query = f"SELECT distinct workflow_email FROM cifa.workflow_stakeholder where workflow_id={workflow_id}"
                users_email = self.iom_utils.run_query(query, "SELECT")

                de_acknowledgers = [user_email.get('workflow_email') for user_email in users_email]

                get_workflow_info_query = (
                    f"SELECT * from workflow.workflow where id = {workflow_id}"
                )
                workflow_details = self.iom_utils.run_query(get_workflow_info_query, "SELECT")
                if workflow_details:
                    logger.debug(workflow_details)
                    if action == "move_to_pending_hw_arrival":
                        self.send_mail(
                            ",".join(de_to),
                            f"Workflow #{workflow_id} Moved to Pending HW Arrival",
                            f"The Workflow #<b><a href ='https://networktools.comcast.net/bom/html/order.php?id={workflow_id}'>{workflow_id}</a></b> has been moved to Pending HW Arrival.<br/><b>Workflow Title: </b>{workflow_details[0]['title']}<br/><br/><b>Current Action:</b>Moved to Pending HW Arrival<br/><b>Current Action triggered by:</b> NetEng Team<br/>",
                            ",".join(de_acknowledgers),
                            "",
                            "",
                            True,
                        )
                    elif action == "move_to_wh_fulfillment":
                        self.send_mail(
                            ",".join(de_to),
                            f"Workflow #{workflow_id} Moved to Warehouse Fullfillment",
                            f"The Workflow #<b><a href ='https://networktools.comcast.net/bom/html/order.php?id={workflow_id}'>{workflow_id}</a></b> has been moved to Warehouse Fullfillment.<br/><b>Workflow Title: </b>{workflow_details[0]['title']}<br/><br/><b>Current Action:</b>Moved to Warehouse Fullfillment<br/><b>Current Action triggered by:</b> NetEng Team<br/>",
                            ",".join(de_acknowledgers),
                            "",
                            "",
                            True,
                        )
                    elif action == "move_wh_completed":
                        self.send_mail(
                            ",".join(de_to),
                            f"Workflow #{workflow_id} Moved to Warehouse Fullfillment Completed",
                            f"The Workflow #<b><a href ='https://networktools.comcast.net/bom/html/order.php?id={workflow_id}'>{workflow_id}</a></b> has been moved to Warehouse Fullfillment Completed.<br/><b>Workflow Title: </b>{workflow_details[0]['title']}<br/><br/><b>Current Action:</b>Moved to Warehouse Fullfillment Completed<br/><b>Current Action triggered by:</b> NetEng Team<br/>",
                            ",".join(de_acknowledgers),
                            "",
                            "",
                            True,
                        )
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def send_mail(self, to, subject, message, cc, param1, param2, https):
        try:
            email_data = {}
            email_data["Subject"] = subject
            email_data["Message"] = message
            email_data['to'] = to
            # email_data["to"] = ",".join("marimuthu_velayutham@comcast.com")
            email_data['cc'] = cc
            IomUtils.send_email(email_data)
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")


if __name__ == "__main__":
    WorkflowMove()

