import traceback
from datetime import datetime
from json import dumps

from icputils import util
from icputils.iom_utils import IomUtils
from logger import logger

logger = logger.setup_logger()


class RmaDb:
    def __init__(self):
        self.iom_utils = IomUtils()
        self.matrix_utils = IomUtils(db_name="matrix_db", schema_name='matrix')
        self.rma_utils = IomUtils(db_name="rma_db")
        self.rma_db()

    def rma_db(self):
        try:
            start_time = datetime.now()
            util.start()
            insert_result = {}
            insert_result = self.insert_divisions(insert_result)
            insert_result = self.insert_markets(insert_result)
            insert_result = self.insert_systems(insert_result)
            insert_result = self.insert_status(insert_result)
            insert_result = self.insert_vendors(insert_result)
            insert_result = self.insert_device_parts(insert_result)
            insert_result = self.insert_devices(insert_result)
            insert_result = self.insert_rmas(insert_result)

            logger.debug(dumps(insert_result, indent=2))

            end_time = datetime.now()
            self.iom_utils.calculate_run_time(start_time, end_time, "rma_db", insert_result, "rma_db")
        except Exception as e:
            logger.exception(f"Exception occurred in rma_db: {e}, {traceback.format_exc()}")

    def insert_divisions(self, insert_result):
        try:
            from_table = "rmaportal.divisions"
            to_table = "rma.divisions"
            query = f"SELECT id, `name` AS divisionName FROM {from_table}"
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True)
        except Exception as e:
            logger.exception(f"Exception occurred in insert_divisions: {e}, {traceback.format_exc()}")
        return insert_result

    def insert_markets(self, insert_result):
        try:
            from_table = "rmaportal.markets"
            to_table = "rma.markets"
            query = f"SELECT id, `name` AS marketName, division_id AS divisionId FROM {from_table}"
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True)
        except Exception as e:
            logger.exception(f"Exception occurred in insert_markets: {e}, {traceback.format_exc()}")
        return insert_result

    def insert_systems(self, insert_result):
        try:
            from_table = "rmaportal.systems"
            to_table = "rma.systems"
            query = f"SELECT id, `name` AS systemName, market_id AS marketId FROM {from_table}"
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True)
        except Exception as e:
            logger.exception(f"Exception occurred in insert_systems: {e}, {traceback.format_exc()}")
        return insert_result

    def insert_status(self, insert_result):
        try:
            from_table = "rmaportal.statuses"
            to_table = "rma.status"
            query = f"SELECT id, `name` AS statusName FROM {from_table}"
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True)
        except Exception as e:
            logger.exception(f"Exception occurred in insert_status: {e}, {traceback.format_exc()}")
        return insert_result

    def insert_vendors(self, insert_result):
        try:
            from_table = "rmaportal.vendors"
            to_table = "rma.vendors"
            query = f"SELECT id, `name` AS vendorName FROM {from_table}"
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True)
        except Exception as e:
            logger.exception(f"Exception occurred in insert_vendors: {e}, {traceback.format_exc()}")
        return insert_result

    def insert_device_parts(self, insert_result):
        try:
            from_table = "rmaportal.device_parts"
            to_table = "rma.device_parts"
            query = f"SELECT id, `number` AS partNumber, `name` AS partName, vendor_id AS vendorId, cost FROM {from_table}"
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True)
        except Exception as e:
            logger.exception(f"Exception occurred in insert_device_parts: {e}, {traceback.format_exc()}")
        return insert_result

    def insert_devices(self, insert_result):
        try:
            from_table = "rmaportal.devices"
            to_table = "rma.devices"
            query = f"SELECT id, fqdn AS fqdnName, ip_address_string AS ipv4 FROM {from_table}"
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True)
        except Exception as e:
            logger.exception(f"Exception occurred in insert_devices: {e}, {traceback.format_exc()}")
        return insert_result

    def insert_rmas(self, insert_result):
        try:
            from_table = "rmaportal.rmas"
            to_table = "rma.rmas"
            query = f"""
                SELECT 
                    rmas.id,
                    rmas.device_part_id AS partId,
                    rmas.vendor_id AS vendorId,
                    rmas.serial_number_sent AS defective_sn,
                    rmas.serial_number_received AS replacement_sn,
                    rmas.spare_device_part_serial_number AS spare_sn,
                    rmas.work_order_number AS woNumber,
                    rmas.device_id AS deviceId,
                    rmas.division_id AS divisionId,
                    rmas.market_id AS marketId,
                    rmas.system_id AS systemId,
                    rmas.status_id AS statusId,
                    DATE_FORMAT(rmas.opened_date, '%Y-%m-%d') AS openDate,
                    cm.`number` AS cm_number
                FROM
                    {from_table}
                        LEFT JOIN
                    rmaportal.cm_tickets cm ON cm.id = rmas.tts_rma_ticket_id
                WHERE
                    rmas.is_active = 1
                """
            insert_result = self.copy_data_between_tables(insert_result, query, to_table, from_table, truncate=True, filter_data="rma")
        except Exception as e:
            logger.exception(f"Exception occurred in insert_rmas: {e}, {traceback.format_exc()}")
        return insert_result

    def copy_data_between_tables(self, insert_result, query, to_table, from_table, truncate=False, filter_data=None):
        try:
            select_result = self.rma_utils.get_pagination_result(query)
            if select_result:
                if filter_data == "rma":
                    select_result = RmaDb.filter_rma_data(select_result)
                result, duplicate_count, unique_count = self.matrix_utils.insert_data(select_result, to_table, truncate=truncate)
                if result:
                    message = f"Data is copied from {from_table} to {to_table}, count: {result}"
                else:
                    message = f"Data is not copied from {from_table} to {to_table}"
            else:
                message = f"No data found to copy from {from_table} to {to_table}"
        except Exception as e:
            message = f"Exception occurred in copy_data_between_tables: {e}, {traceback.format_exc()}"
            logger.exception(message)
        insert_result[f"{from_table} to {to_table} message"] = message
        logger.debug(message)
        return insert_result

    @staticmethod
    def filter_rma_data(results):
        return_result = []
        try:
            for result in results:
                return_result.append({
                    "id": result.get('id'),
                    "partId": result.get('partId'),
                    "vendorId": result.get('vendorId'),
                    "defective_sn": RmaDb.filter_sn(result.get('defective_sn')),
                    "replacement_sn": RmaDb.filter_sn(result.get('replacement_sn')),
                    "spare_sn": RmaDb.filter_sn(result.get('spare_sn')),
                    "woNumber": RmaDb.filter_wo(result.get('woNumber')),
                    "deviceId": result.get('deviceId'),
                    "divisionId": result.get('divisionId'),
                    "marketId": result.get('marketId'),
                    "systemId": result.get('systemId'),
                    "statusId": result.get('statusId'),
                    "openDate": result.get('openDate'),
                    "cm_number": result.get('cm_number')
                })
        except Exception as e:
            logger.exception(f"Exception occurred in filter_rma_data: {e}, {traceback.format_exc()}")
        return return_result

    @staticmethod
    def filter_sn(sn):
        try:
            if sn is None:
                return None
            else:
                try:
                    sn = str(sn)
                except Exception as e:
                    logger.exception(f"Exception: {e}, {traceback.format_exc()}")
                    return sn

                if len(sn) <= 5 or sn.lower() == 'unknown':
                    return None
                else:
                    return sn.strip()
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")
            return None

    @staticmethod
    def filter_wo(wo):
        try:
            if wo is None:
                return None
            else:
                try:
                    wo = int('0' + ''.join(filter(str.isdigit, str(wo))))
                except Exception as e:
                    logger.exception(f"Exception: {e}, {traceback.format_exc()}")
                    return None

                if 10000 < wo < 100000:
                    return wo
                else:
                    return None
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")
            return None


if __name__ == '__main__':
    RmaDb()

