import sys 
import json

PART_MAPPING = {}

import icputils.config
from icputils import util
from icputils.iom_utils import IomUtils
from logger import logger
import re
BADCHARS=re.compile('[^\x20-\x7E\n\r]')
def main():
    iom_utils = IomUtils()
    matrx_iom_utils = IomUtils(db_name="matrix_db", schema_name='matrix') 

    set_part_mapping(matrx_iom_utils)
    unknown_sites = get_unknown_sites(matrx_iom_utils)
    site_report = get_site_report(matrx_iom_utils)
    for (site_id, report) in site_report.items():
        threshold_status = get_threshold_status(report['optics'], report['threshold'])
        fulfillment_status = get_fulfillment_status(report['optics'], report['fulfillment'], report['threshold'])
        set_status(matrx_iom_utils, site_id, threshold_status, fulfillment_status, unknown_sites)

    delete_old_entries(matrx_iom_utils)

def clean_text(text): #removes invalid characters
	if text == None:
		return None
	else:
		try:
			return re.sub(BADCHARS,'',text)
		except:
			return re.sub(BADCHARS,'',str(text))

def delete_old_entries(matrx_iom_utils):
    query = """
    DELETE FROM matrix.bsne_optics_site_status
    WHERE site_id NOT IN (
        SELECT DISTINCT f.site_id
        FROM matrix.bsne_optics_report r
        JOIN matrix.matrix2_fqdn f ON f.id = r.fqdn_id
        WHERE r.active = 1 AND r.compatible = 0 AND r.replacement_part_number IS NOT NULL
    )
    """
    matrx_iom_utils.run_query(query, "DELETE")


def set_status(matrx_iom_utils, site_id, threshold_status, fulfillment_status, unknown_sites):
    query = f"""
    INSERT INTO matrix.bsne_optics_site_status (site_id, threshold_status, fulfillment_status)
        VALUES ({site_id}, {threshold_status}, {fulfillment_status})
    ON DUPLICATE KEY UPDATE
        threshold_status = VALUES(threshold_status),
        fulfillment_status = VALUES(fulfillment_status)
    """
    if site_id in unknown_sites:
        threshold_status = 'Unknown Part'
    matrx_iom_utils.run_query(query, "INSERT")


def set_part_mapping(matrx_iom_utils):
    query = """
    SELECT part_number, bom_part_id
    FROM matrix.bsne_optics_part
    """
    cursor = matrx_iom_utils.run_query(query, "SELECT")
    for row in cursor:
        PART_MAPPING[row['part_number']] = row['bom_part_id']


def get_threshold_status(request, ordered):
    for part in request:
        if part is None:
            return 'Unmapped Part'

    for part in request:
        if not PART_MAPPING.get(part, 0):
            return 'Missing Part'

    if len(ordered) == 0:
        return 'Need Primary'

    for (req_part, need) in request.items():
        if ordered.get(req_part, 0) >= need:
            continue
        else:
            return 'Need Delta'

    return 'Complete'


def get_fulfillment_status(request, ordered, threshold):
    for part in request:
        if part is None:
            return 'Unmapped Part'

    for part in request:
        if not PART_MAPPING.get(part, 0):
            return 'Missing Part'

    for (req_part, need) in threshold.items():
        if threshold.get(req_part, 0) >= need:
            continue
        else:
            return 'Need Threshold'

    if len(ordered) == 0:
        return 'Need Primary'

    for (req_part, need) in request.items():
        if ordered.get(req_part, 0) >= need:
            continue
        else:
            return 'Need Delta'

    return 'Complete'


def get_unknown_sites(matrx_iom_utils):
    result = {}
    query = """
    SELECT f.site_id, SUM(IF(r.part_number = 'CiscoCompatibleOptics' OR r.part_number = '' OR r.part_number = '0.0' OR r.part_number = 'eb557b7a350bda26', 1, 0)) AS unknown_count
    FROM matrix.bsne_optics_report r
    JOIN matrix.matrix2_fqdn f ON f.id = r.fqdn_id
    WHERE r.last_updated >= CURDATE() - INTERVAL 2 DAY
    GROUP BY f.site_id
    HAVING unknown_count > 0
    """
    cursor = matrx_iom_utils.run_query(query, "SELECT")
    for row in cursor:
        result[row['site_id']] = row['unknown_count']

    return result


def get_site_report(matrx_iom_utils):
    result = {}
    query = """
    SELECT f.site_id, r.replacement_part_number, COUNT(*) AS optic_count
    FROM matrix.bsne_optics_report r
    JOIN matrix.matrix2_fqdn f ON f.id = r.fqdn_id
    WHERE r.active = 1 AND r.compatible = 0
    GROUP BY f.site_id, replacement_part_number
    ORDER BY site_id, replacement_part_number
    """

    cursor = matrx_iom_utils.run_query(query, "SELECT")
    for row in cursor:
        if row['site_id'] not in result:
            result[row['site_id']] = {'optics': {}, 'threshold': {}, 'fulfillment': {}}

        result[row['site_id']]['optics'][row['replacement_part_number']] = row['optic_count']

    query = """
    SELECT site_id, bom_id, bom_type, JSON_EXTRACT(part_order, '$.order') AS part_order
    FROM matrix.bsne_optics_migration_bom
    ORDER BY site_id
    """

    cursor = matrx_iom_utils.run_query(query, "SELECT")
    for row in cursor:
        row['part_order'] = json.loads(row['part_order'])
        if row['site_id'] in result:
            if row['bom_type'] in ['Threshold', 'Procurement']:
                for part in row['part_order']:
                    if part['success']:
                        if part['optic'] not in result[row['site_id']]['threshold']:
                            result[row['site_id']]['threshold'][part['optic']] = 0
                        result[row['site_id']]['threshold'][part['optic']] += int(part['count'])

            if row['bom_type'] in ['Fulfillment', 'Procurement']:
                for part in row['part_order']:
                    if part['success']:
                        if part['optic'] not in result[row['site_id']]['fulfillment']:
                            result[row['site_id']]['fulfillment'][part['optic']] = 0
                        result[row['site_id']]['fulfillment'][part['optic']] += int(part['count'])

    return result


if __name__ == '__main__':
    main()

