import datetime
import traceback
import urllib.parse
from base64 import b64encode
from json import dumps

from requests import request

from icputils import database
from logger import logger

logger = logger.setup_logger()
from os import path
import sys
class Kibana:
    def __init__(self):
        pass

    @staticmethod
    def get_config_details(key='kibana', index=None):
        url = dashboard_url = None
        headers = {}
        try:
            kibana_config = database.get_config_data(key)

            url = kibana_config['url']
            index = kibana_config.get('iomscripts') if not index else index
            username = kibana_config['username']
            password = kibana_config['password']
            dashboard_url = kibana_config.get('dashboard_url')

            token = b64encode((username + ':' + password).encode()).decode()

            headers = {
                'Content-Type': 'application/json',
                'Authorization': f'Basic {token}'
            }
        except Exception as e:
            logger.exception(f"Exception occurred in get_config_details: {e}, {traceback.format_exc()}")
        return url, index, headers, dashboard_url

    @staticmethod
    def add_kibana_logs_and_send_failure_email(log_messages, start_time):
        try:
            if log_messages:

                from icputils.iom_utils import script_owner as owner

                from icputils.iom_utils import script_id as script_id
                from icputils.iom_utils import IomUtils
                url, index, headers, dashboard_url = Kibana.get_config_details()

                Kibana.send_script_failure_email(log_messages, index, dashboard_url, start_time, script_id)
                mongo_client = database.mongo_con_db('insight_history') 
                collection = mongo_client.iom_history.filemaker2_script_execution_data     
                iom_utils = IomUtils()
                ran = {}
                ran['script_owner'] = owner
                ran['script_id'] = script_id
                ran['script_name'] = path.basename(sys.argv[0]) 
                ran['created_at'] = datetime.datetime.now().strftime("%Y-%m-%dT%H:%M:%SZ")
                ran['issue_raised'] = False
                ran['issue'] =  'exception'
                ran['status'] =  'not completed' 
                ran['not_updated_data'] = log_messages.pop()
                if(ran['not_updated_data'].get('level') == 'ERROR'):
                    iom_utils.insert_data_mongo([
                        ran
                    ], collection, 'iom_history.filemaker2_script_execution_data')

                url = f"{url}{index}/_bulk"

                count = len(log_messages)
                logger.debug(f"Adding logs to kibana, count: {count}")
                limit = 1000

                for start_index in range(0, len(log_messages), limit):

                    end_index = start_index + limit
                    chunk = log_messages[start_index:end_index]
                    payload = ""

                    for log in chunk:
                        log['owner'] = owner
                        create = {"create": {"_index": index}}
                        payload = f"{payload}{dumps(create)}\n{dumps(log)}\n"

                    response = request("POST", url, headers=headers, data=payload)

                    if response.status_code == 200:
                        logger.debug(f"Successfully added {len(chunk)} logs to kibana")
                    else:
                        logger.debug(f"Failed in adding {len(chunk)} logs to kibana. Response: {response.json()}, status code: {response.status_code}")

        except Exception as e:
            logger.exception(f"Exception occurred in add_kibana_logs_and_send_failure_email: {e}, {traceback.format_exc()}")

    @staticmethod
    def send_script_failure_email(log_messages, index, dashboard_url, start_time, script_id):
        try:
            from icputils.iom_utils import IomUtils
            exception_list = []
            script_name = None

            uuid = log_messages[0]["uuid"]

            for log in log_messages:
                script_name = log.get('script_name')
                level = log.get('level')
                if level and level.lower() in ('error', 'exception'):
                    exception_list.append(log)

            end_time = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")

            if exception_list:
                kibana_link = Kibana.get_kibana_link(uuid, index, dashboard_url, start_time, end_time, level="ERROR")
                short_script_name = script_name.split('/')[-1]
                kwargs = {
                    "kibana_link": kibana_link,
                    "script_name": short_script_name,
                    "uuid": uuid
                }
                IomUtils.send_email_from_api(**kwargs)
                Kibana.insert_failure_record(script_id, kibana_link)
            else:
                kibana_link = Kibana.get_kibana_link(uuid, index, dashboard_url, start_time, end_time)
                Kibana.insert_success_record(script_id, start_time, end_time, kibana_link)
        except Exception as e:
            logger.exception(f"Exception occurred in send_script_failure_email: {e}, {traceback.format_exc()}")

    @staticmethod
    def get_kibana_link(uuid, index, dashboard_url, start_time, end_time, level=None):
        kibana_link = None
        try:
            if level:
                search_string = f'uuid : {uuid} and level : "ERROR" '
            else:
                search_string = f'uuid : {uuid} '

            search_string = Kibana.encode_string(search_string)

            kibana_link = f"""{dashboard_url}#/?_g=(filters:!(),refreshInterval:(pause:!t,value:60000),time:(from:'{start_time}',to:'{end_time}'))&_a=(columns:!(script_name,message,level,owner,uuid),filters:!(),index:'{index}*',interval:auto,query:(language:kuery,query:'{search_string}'),sort:!(!('@timestamp',desc)))"""

        except Exception as e:
            logger.exception(f"Exception occurred in get_kibana_link: {e}, {traceback.format_exc()}")
        return kibana_link

    @staticmethod
    def search_kibana_logs(start_time, end_time, search_params):
        logs_list = []
        try:
            url, index, headers, dashboard_url = Kibana.get_config_details()
            url = f"{url}{index}/_search"

            for search_param in search_params:
                query = {
                    "bool": {
                        "filter": [
                            {
                                "range": {
                                    "@timestamp": {
                                        "gte": f"{start_time}",
                                        "lt": f"{end_time}"
                                    }
                                }
                            },
                            {
                                "wildcard": {
                                    "message": f"*{search_param}*"
                                }
                            }
                        ]
                    }
                }
                logs_list.extend(Kibana.get_pagination_data(query, url, headers))

            logs_list = [
                {
                    'id': logs_dict.get('_id'),
                    'timestamp': logs_dict.get('_source').get('@timestamp'),
                    'script_name': logs_dict.get('_source').get('script_name')
                }
                for logs_dict in logs_list
            ]
        except Exception as e:
            logger.exception(f"Exception occurred in search_kibana_logs: {e}, {traceback.format_exc()}")
        return logs_list

    @staticmethod
    def get_pagination_data(query, url, headers, size=10000):
        result = []
        try:
            payload = dumps({
                "query": query,
                "_source": True,
                "sort": [
                    {
                        "@timestamp": "asc"
                    }
                ],
                "size": size
            })

            logger.debug(f"url: {url}")
            logger.debug(f"headers: {headers}")
            logger.debug(f"payload: {payload}")

            response = request("GET", url, headers=headers, data=payload)

            if response.status_code == 200:
                total_records = response.json().get('hits', {}).get('total', {}).get('value')
                logger.debug(f"total_records: {total_records}")
                if total_records > size:
                    return Kibana.get_pagination_data(query, url, headers, size=total_records)
                result = response.json().get('hits', {}).get('hits', [])
        except Exception as e:
            logger.exception(f"Exception occurred in get_pagination_data: {e}, {traceback.format_exc()}")
        return result

    @staticmethod
    def encode_string(string):
        encoded_parts = []
        for part in string.split(" "):
            encoded_parts.append(urllib.parse.quote(part, safe=":"))
        return "%20".join(encoded_parts)

    @staticmethod
    def insert_failure_record(script_id, kibana_link):
        try:
            cnx, cursor = database.mysql_con('matrix_db')
            cursor.execute("INSERT INTO matrix.scripts_history (flag, failed_date, script_id, kibana_link) VALUES (0, NOW(), %s, %s)", (script_id, kibana_link,))
            cnx.close()
        except Exception as e:
            logger.exception(f"Exception occurred in insert_failure_record: {e}, {traceback.format_exc()}")

    @staticmethod
    def insert_success_record(script_id, start_time, end_time, kibana_link):
        try:
            start_time = datetime.datetime.strptime(start_time, '%Y-%m-%dT%H:%M:%S')
            end_time = datetime.datetime.strptime(end_time, '%Y-%m-%dT%H:%M:%S')
            runtime = int((end_time - start_time).total_seconds())

            cnx, cursor = database.mysql_con('matrix_db')
            cursor.execute("INSERT INTO matrix.scripts_history (script_id, stamp, run_time, kibana_link) VALUES (%s, NOW(), %s, %s)", (script_id, runtime, kibana_link,))
            cnx.close()
        except Exception as e:
            logger.exception(f"Exception occurred in insert_success_record: {e}, {traceback.format_exc()}")

    @staticmethod
    def search_kibana_logs_v2(index, recent_timestamp, date_time_field):
        logs_list = []
        final_logs_list = []
        total_records = None
        try:
            base_url, index, headers, dashboard_url = Kibana.get_config_details(key='elasticsearch', index=index)
            url = f"{base_url}/{index}/_search?scroll=1m"

            size = 10000
            payload = {
                "_source": True,
                "sort": [
                    {
                        f"{date_time_field}": "asc"
                    }
                ],
                "size": size
            }

            if recent_timestamp:
                payload['query'] = {
                    "bool": {
                        "filter": [
                            {
                                "range": {
                                    f"{date_time_field}": {
                                        "format": "strict_date_optional_time",
                                        "gte": f"{recent_timestamp}"
                                    }
                                }
                            }
                        ]
                    }
                }

            logger.debug(f"url: {url}")
            logger.debug(f"headers: {headers}")
            logger.debug(f"payload: {payload}")

            response = request("GET", url, headers=headers, data=dumps(payload))

            if response.status_code == 200:
                total_records = response.json().get('hits', {}).get('total', {}).get('value')
                logger.debug(f"total_records: {total_records}")
                logs_list = response.json().get('hits', {}).get('hits', [])
                if total_records > size:
                    scroll_id = response.json().get('_scroll_id')
                    logs_list = Kibana.get_pagination_data_v2(base_url, headers, logs_list, total_records, scroll_id)
        except Exception as e:
            logger.exception(f"Exception occurred in search_kibana_logs: {e}, {traceback.format_exc()}")
        if logs_list:
            final_logs_list = [logs_dict.get('_source') for logs_dict in logs_list]
        return final_logs_list, total_records

    @staticmethod
    def get_pagination_data_v2(base_url, headers, logs_list, total_records, scroll_id):
        try:
            url = f"{base_url}/_search/scroll"
            payload = dumps({
                "scroll": "1m",
                "scroll_id": f"{scroll_id}"
            })
            response = request("POST", url, headers=headers, data=payload)
            if response.status_code == 200:
                logs_list.extend(response.json().get('hits', {}).get('hits', []))
                if total_records > len(logs_list):
                    return Kibana.get_pagination_data_v2(base_url, headers, logs_list, total_records, scroll_id)
        except Exception as e:
            logger.exception(f"Exception occurred in get_pagination_data: {e}, {traceback.format_exc()}")
        return logs_list

