import traceback
from datetime import datetime
from re import match

from filemaker.file_maker_api import FileMakerAPI
from icputils import util
from icputils.iom_utils import IomUtils
from logger import logger

logger = logger.setup_logger()


class UpdateLightwaveCompletedDate:
    def __init__(self):
        util.start()
        self.iom_utils = IomUtils()
        self.file_maker_api = FileMakerAPI(iom_utils=self.iom_utils, IomUtils=IomUtils)
        self.update_lightwave_completed_date()

    def update_lightwave_completed_date(self):
        try:
            query = """
                SELECT
                    woNumber AS WOPrefix_Number
                FROM
                    bom_database.rack_wo_creation_log
                WHERE
                    lightwave_completion_date IS NULL;
            """
            wo_numbers = self.iom_utils.run_query(query, "SELECT")

            z_mod_log_list = IomUtils.start_thread(self.invoke_api, wo_numbers)

            self.update_data(z_mod_log_list)

        except Exception as e:
            logger.exception(f"Exception occurred in update_lightwave_completed_date: {e}, {traceback.format_exc()}")

    def invoke_api(self, wo_number):
        z_mod_log_list = []
        try:
            query = [wo_number]
            result = self.file_maker_api.get_pagination_data("ComcastOne", "ComcastOne/layouts/API_WOModLog/_find", "API_WOModLog", query, from_thread=True)
            if result:
                z_mod_log = result[0].get('response', {}).get('data', [{}])[0].get('fieldData', {}).get('zModLog', {})
                mod_log_list = z_mod_log.split('\r') if z_mod_log else []
                date_time = None
                for mod_log_str in mod_log_list:
                    mod_log_str_list = mod_log_str.split('\t') if mod_log_str else []
                    if len(mod_log_str_list) == 7 and mod_log_str_list[3] == 'LabStatus' and mod_log_str_list[4] == 'Lightwave':
                        date = mod_log_str_list[0]
                        if match(r'\d{1,2}/\d{1,2}/\d{4}', date):
                            date = datetime.strptime(date, "%m/%d/%Y") if date else None
                        time = mod_log_str_list[1]
                        if match(r'\d{1,2}:\d{2}:\d{2} [APap][Mm]', time):
                            time = datetime.strptime(time, "%I:%M:%S %p") if time else None
                        elif match(r'\d{1,2}:\d{2} [APap][Mm]', time):
                            time = datetime.strptime(time, "%I:%M %p") if time else None

                        date_time = datetime.combine(date.date(), time.time()) if date and time else None

                if date_time:
                    z_mod_log_list.append({
                        wo_number['WOPrefix_Number']: date_time
                    })
        except Exception as e:
            logger.exception(f"Exception occurred in invoke_api: {e}, {traceback.format_exc()}")
        return z_mod_log_list

    def update_data(self, z_mod_log_list):
        try:
            for z_mod_log in z_mod_log_list:
                for wo_number, lightwave_completion_date in z_mod_log.items():
                    query = f"""
                        UPDATE bom_database.rack_wo_creation_log
                        SET
                            lightwave_completion_date = '{lightwave_completion_date}'
                        WHERE
                            woNumber = '{wo_number}';
                    """
                    self.iom_utils.run_query(query, "UPDATE")
        except Exception as e:
            logger.exception(f"Exception occurred in update_data: {e}, {traceback.format_exc()}")


if __name__ == '__main__':
    UpdateLightwaveCompletedDate()

