import json
import traceback
from datetime import datetime

from requests import request

from icputils import util
from icputils.iom_utils import IomUtils
from logger import logger

logger = logger.setup_logger()


class CreateVcmtsWo:
    def __init__(self):
        self.iom_utils = IomUtils()
        self.create_vcmts_wo()

    def create_vcmts_wo(self):
        try:
            start_time = datetime.now()
            util.start()

            por_gears = CreateVcmtsWo.get_por_gears_data()

            current_year, current_quarter, next_year, next_quarter = CreateVcmtsWo.get_current_and_next_quarter()

            vcmts_wo_creation_data = self.get_vcmts_wo_creation_data(current_year, current_quarter, por_gears)

            # vcmts_wo_creation_data = {
            #     "2025": {
            #         "1": {
            #             "CPOD": {
            #                 "February": 4
            #             },
            #             "PPOD": {
            #                 "February": 16
            #             }
            #         }
            #     }
            # }

            vcmts_wo_creation_result = self.create_vcmts_wos(vcmts_wo_creation_data)

            end_time = datetime.now()
            self.iom_utils.calculate_run_time(start_time, end_time, "create_vcmts_wo", vcmts_wo_creation_result, "create_vcmts_wo")
        except Exception as e:
            logger.exception(f"Exception occurred in create_vcmts_wo: {e}, {traceback.format_exc()}")

    @staticmethod
    def get_por_gears_data():
        por_gears = {}
        try:
            year = datetime.now().year
            url = f"https://insight.comcast.com/api/vcmts/pors-gears-kpi?por_year={year}"
            headers = {
                'Content-Type': 'application/json'
            }
            response = request("GET", url, headers=headers)
            if response.status_code == 200:
                response_json = response.json()
                for por_gear in response_json.get('result', []):
                    if por_gear['is_rack'] == 1:
                        por_gears.setdefault(por_gear['gear_name'], por_gear)

        except Exception as e:
            logger.exception(f"Exception occurred in get_por_gears_data: {e}")
        return por_gears

    @staticmethod
    def get_current_and_next_quarter():
        current_month = datetime.now().month
        current_year = datetime.now().year
        current_quarter = (current_month - 1) // 3 + 1

        if current_quarter == 4:
            next_quarter = 1
            next_year = current_year + 1
        else:
            next_quarter = current_quarter % 4 + 1
            next_year = current_year

        return current_year, current_quarter, next_year, next_quarter

    def get_vcmts_wo_creation_data(self, year, quarter, por_gears):
        vcmts_wo_creation_data = {}
        try:
            vcmts_wo_title_dict = {
                "Video Pod (Gen 3.0) - DAC": {
                    "device_type": "DAC"
                },
                "Video Pod (Gen 3.0) - DNCS": {
                    "device_type": "DNCS"
                },
                "Control Pod (Gen 3.0)": {
                    "device_type": "CPOD"
                },
                "P-POD (Gen3.0)": {
                    "device_type": "PPOD"
                }
            }

            vcmts_wos_from_db = self.get_vcmts_wos_from_db()

            vcmts_wos_from_api = {}
            for gear_name, por_gear in por_gears.items():
                device_type = vcmts_wo_title_dict.get(gear_name, {}).get('device_type')
                if device_type:
                    allocation = int(por_gear.get(f'_q{quarter}_alloc'))
                    if allocation > 0:
                        months_in_quarter = {
                            1: ["January", "February", "March"],
                            2: ["April", "May", "June"],
                            3: ["July", "August", "September"],
                            4: ["October", "November", "December"]
                        }

                        quarter_months = months_in_quarter[quarter]
                        allocation_distribution = [0, 0, 0]

                        for i in range(allocation):
                            allocation_distribution[i % 3] += 1

                        month_counts = {month: count for month, count in zip(quarter_months, allocation_distribution)}
                        vcmts_wos_from_api.setdefault(year, {}).setdefault(quarter, {}).setdefault(device_type, {}).update(month_counts)

            for year, quarters in vcmts_wos_from_api.items():
                for quarter, vcmts_wos in quarters.items():
                    for gear_name, vcmts_wo in vcmts_wos.items():
                        for month, allocation in vcmts_wo.items():
                            api_count = allocation
                            db_count = vcmts_wos_from_db.get(year, {}).get(quarter, {}).get(gear_name, {}).get(month, 0)
                            difference = api_count - db_count
                            if difference > 0:
                                vcmts_wo_creation_data.setdefault(year, {}).setdefault(quarter, {}).setdefault(gear_name, {})[month] = difference

        except Exception as e:
            logger.exception(f"Exception occurred in get_vcmts_wo_creation_data: {e}")
        return vcmts_wo_creation_data

    def get_vcmts_wos_from_db(self):
        vcmts_wos_from_db = {}
        try:
            query = """
                    SELECT 
                        `year`,
                        `quarter`,
                        `month`,
                        `deviceType`,
                        COUNT(id) AS `count`
                    FROM
                        bom_database.vcmts_wo_creation_log
                    GROUP BY `year` , `quarter` , `month` , `deviceType`;
                """
            results = self.iom_utils.run_query(query, "SELECT")
            for result in results:
                vcmts_wos_from_db.setdefault(result['year'], {}).setdefault(result['quarter'], {}).setdefault(result['deviceType'], {}).setdefault(result['month'], result['count'])
        except Exception as e:
            logger.exception(f"Exception occurred in get_vcmts_wos_from_db: {e}")
        return vcmts_wos_from_db

    def create_vcmts_wos(self, vcmts_wo_creation_data):

        failure_list = []
        insert_list = []
        try:
            version = "4.0"
            for year, year_data in vcmts_wo_creation_data.items():
                for quarter, quarter_data in year_data.items():
                    for device, device_data in quarter_data.items():
                        for month, allocation in device_data.items():
                            if allocation > 0:
                                url = "https://iom.comcast.net/api/filemaker/create_vcmts_wo"
                                payload = {
                                    "WOType": "vCMTSRack",
                                    "NumOfWO": str(allocation),
                                    "StartingFrom": "1",
                                    "Type": str(device),
                                    "Version": version,
                                    "MonthName": str(month)
                                }

                                headers = {
                                    'Content-Type': 'application/json'
                                }
                                response = request("POST", url, headers=headers, data=json.dumps(payload))
                                if response.status_code == 200:
                                    wo_list = response.json().get('wo_list')
                                    if wo_list:
                                        for wo_number in wo_list:
                                            insert_list.append({
                                                "year": year,
                                                "quarter": quarter,
                                                "deviceType": device,
                                                "month": month,
                                                "woNumber": wo_number,
                                                "version": version,
                                                "team": "VCMTS"
                                            })
                                else:
                                    failure_list.append({
                                        "year": year,
                                        "quarter": quarter,
                                        "deviceType": device,
                                        "month": month,
                                        "woNumber": None,
                                        "version": version
                                    })
            if insert_list:
                self.iom_utils.insert_data(insert_list, "bom_database.rack_wo_creation_log")

        except Exception as e:
            logger.exception(f"Exception occurred in create_vcmts_wos: {e}")

        return {
            'failure_list': failure_list,
            'insert_list': insert_list
        }


if __name__ == '__main__':
    CreateVcmtsWo()

