import json
import traceback
from datetime import datetime

import pytz
import requests

from icputils import util
from icputils.iom_utils import IomUtils
from logger import logger

logger = logger.setup_logger()


class UpdateWoValidation:
    def __init__(self):
        util.start()
        self.iom_utils = IomUtils()
        self.update_vcmts_work_orders()
        self.update_dashboard_work_orders()
        self.update_wo_validation()

    def update_vcmts_work_orders(self):
        try:
            url = "https://iom.comcast.net/api/filemaker/on_demand"

            payload = json.dumps({
                "action": "update_vcmts_wo"
            })
            headers = {
                'Content-Type': 'application/json'
            }

            logger.debug("1.1 Start updating vcmts work orders")

            response = requests.request("POST", url, headers=headers, data=payload)
            if response.status_code == 200:
                logger.debug("Successfully updated vcmts work orders")
                est_date_time = datetime.now(pytz.timezone('US/Eastern')).strftime("%Y-%m-%d %H:%M:%S")
                query = f"""
                    UPDATE filemaker2.script_stamp_status 
                    SET last_update = '{est_date_time}'
                    WHERE `script_name` = 'update_vcmts_wo';
                    """
                self.iom_utils.run_query(query, "UPDATE")

            logger.debug("1.2 End updating vcmts work orders")

        except Exception as e:
            logger.exception(f"Exception occurred in update_vcmts_work_orders: {e}, {traceback.format_exc()}")

    def update_dashboard_work_orders(self):
        try:
            logger.debug("2.1 Start updating dashboard work orders")
            query = """
                SELECT 
                    w.woNumber
                FROM
                    filemaker2.wo w
                        LEFT JOIN
                    filemaker2.woStep ws ON ws.stepId = w.stepId
                WHERE
                    w.vcmtsFlag = 1
                        AND ws.stepName IN ('Lab' , 'Shipping', 'Not Started')
                        AND w.title NOT LIKE '%Return rack%'
                        AND w.labStatus NOT IN ('Waiting on Parts')
                GROUP BY w.woNumber;
            """
            results = self.iom_utils.run_query(query, "SELECT")
            wo_numbers = [result['woNumber'] for result in results]

            if wo_numbers:
                api_results = IomUtils.start_thread(UpdateWoValidation.invoke_on_demand, wo_numbers)
                if api_results:
                    logger.debug("Successfully updated dashboard work orders")
                    est_date_time = datetime.now(pytz.timezone('US/Eastern')).strftime("%Y-%m-%d %H:%M:%S")
                    query = f"""
                        UPDATE filemaker2.script_stamp_status 
                        SET last_update = '{est_date_time}'
                        WHERE `script_name` = 'update_dashboard_wo';
                        """
                    self.iom_utils.run_query(query, "UPDATE")
            logger.debug("2.2 End updating dashboard work orders")
        except Exception as e:
            logger.exception(f"Exception occurred in update_dashboard_work_orders: {e}, {traceback.format_exc()}")

    @staticmethod
    def invoke_on_demand(wo_number):
        api_results = []
        try:
            url = "https://iom.comcast.net/api/filemaker/on_demand"

            payload = json.dumps({
                "action": "get_required_wo",
                "wo_number": wo_number
            })
            headers = {
                'Content-Type': 'application/json'
            }

            response = requests.request("POST", url, headers=headers, data=payload)
            if response.status_code == 200:
                print(f"Successfully updated for work order: {wo_number}")
                api_results.append(wo_number)
        except Exception as e:
            logger.exception(f"Exception occurred in invoke_on_demand: {e}, {traceback.format_exc()}")
        return api_results

    def update_wo_validation(self):
        try:
            logger.debug("3.1 Start updating work order validation")
            url = "https://iom.comcast.net/api/vcmts/get_work_orders"

            payload = json.dumps({
                "action": "work_order_details"
            })
            headers = {
                'Content-Type': 'application/json'
            }

            response = requests.request("POST", url, headers=headers, data=payload)
            if response.status_code == 200:
                logger.debug("Successfully updated work order validation")
                est_date_time = datetime.now(pytz.timezone('US/Eastern')).strftime("%Y-%m-%d %H:%M:%S")
                query = f"""
                    UPDATE filemaker2.script_stamp_status 
                    SET last_update = '{est_date_time}'
                    WHERE `script_name` = 'work_order_validation';
                    """
                self.iom_utils.run_query(query, "UPDATE")
            logger.debug("3.2 End updating work order validation")
        except Exception as e:
            logger.exception(f"Exception occurred in update_wo_validation: {e}, {traceback.format_exc()}")


if __name__ == '__main__':
    UpdateWoValidation()

