run_query.code:
def run_query(self, query, query_type='', values=None, bulk_insert=False, insert_no_auto_increment=False, retry=0) -> any:
    result = None
    try:
        if query_type == "SELECT":
            logger.debug(f"Query: {query}")
            if values:
                logger.debug(f"Values: {values}")
            self.cursor.execute(query, values)
            result = self.cursor.fetchall()
        elif query_type == "INSERT":
            if values:
                if len(values) == 1:
                    logger.debug(f"Query: {query}")
                    logger.debug(f"Values: {values}")
                    self.cursor.execute(query, values[0])
                    if self.cursor.rowcount > 0:
                        result = self.cursor.lastrowid
                    if insert_no_auto_increment:
                        result = True
                else:
                    self.cursor.executemany(query, values)
                    result = True
            else:
                logger.debug(f"Query: {query}")
                self.cursor.execute(query)
                if self.cursor.rowcount > 0:
                    result = self.cursor.lastrowid
                if insert_no_auto_increment or bulk_insert:
                    result = True
        else:
            if query_type in ("UPDATE", "DELETE"):
                self.cursor.execute("SET SQL_SAFE_UPDATES = 0")
                if values:
                    self.cursor.executemany(query, values)
                else:
                    logger.debug(f"Query: {query}")
                    self.cursor.execute(query)
                result = True
            else:
                self.cursor.execute(query)
                result = True
    except mysql.connector.Error as e:
        logger.exception(f"Query: {query}")
        logger.exception(f"Values: {values}")
        logger.exception(f"mysql.connector error in run_query: {e}")
        if e.errno in (1213,2006, 2013, 3100, 1290,1205) and retry < 3:
            retry += 1
            logger.warning(f"Connection lost, retry: {retry} after 10 seconds")
            sleep(10)
            self.connect_database()
            return self.run_query(query, query_type, values, bulk_insert, insert_no_auto_increment, retry)
    except MySQLdb.Error as e:
        logger.exception(f"Query: {query}")
        logger.exception(f"Values: {values}")
        logger.exception(f"MySQLdb error in run_query: {e}")
        if e.args[0] in (1213, 2006, 2013, 3100, 1290, 1205) and retry < 3:
            retry += 1
            logger.warning(f"Connection lost, retry: {retry} after 10 seconds")
            sleep(10)
            self.connect_database()
            return self.run_query(query, query_type, values, bulk_insert, insert_no_auto_increment, retry)
    return result

