def remove_duplicate_dicts(duplicate_list):
    unique_list = []
    duplicate_count = unique_count = None
    try:
        duplicate_count = len(duplicate_list)
        logger.debug(f"duplicate_list: {duplicate_count}")
        seen = set()
        for d in duplicate_list:
            if(type(d) is not list and type(d) is not tuple):
                t = tuple(sorted(d.items()))
                if t not in seen:
                    seen.add(t)
                    unique_list.append(d)
        unique_count = len(unique_list)
        logger.debug(f"unique_list: {unique_count}")
    except Exception as e:
        logger.exception(f"Exception occurred in remove_duplicate_dicts: {e}, {traceback.format_exc()}")
    return unique_list, duplicate_count, unique_count

