                    query = f'select modelId from {table_name} where lower(trim(modelName)) = "{original_model_name.lower()}";'
                    result = self.run_query(query, 'SELECT')
                    if result:
                        model_id = result[0].get('modelId')
                    else:
                        model_nick_name = model_nick_name if model_nick_name else original_model_name
