        ids = [result.get('id') for result in results]
        logger.debug(f"Select query result: {len(ids)}")
        if ids:
            status = self.update_query_pagination(update_query, ids, comment)
        else:
            insert_result[f"{comment} message"] = "No data found to update"
    except Exception as e:
        logger.exception(f"Exception occurred in select_and_update: {e}, {traceback.format_exc()}")
    insert_result[comment] = status
    return insert_result

