update_delta_scenario.code:
def update_delta_scenario(matrx_iom_utils):
    # Delta Scenario 1 = MAP_CHANGE, Change of mapping causing different replacement optic
    # Delta Scenario 2 = NEW_PORT, New port showed up in discovery
    # Delta Scenario 3 = OPTIC_CHANGE, seated optic changed
    date_list = fetch_history_dates(matrx_iom_utils)

    history_tracking = {}
    params = []
    init = True
    for datestamp in date_list:
        history = fetch_historical(matrx_iom_utils, datestamp)
        if init:
            init = False
            for port in history:
                identifier = "%s-%s" % (port['fqdn_id'], port['interface_id'])
                history_tracking[identifier] = {
                    'part_number': port['part_number'],
                    'replacement_part_number': port['replacement_part_number'],
                }

        else:
            for port in history:
                identifier = "%s-%s" % (port['fqdn_id'], port['interface_id'])
                if identifier not in history_tracking:
                    history_tracking[identifier] = {
                        'part_number': port['part_number'],
                        'replacement_part_number': port['replacement_part_number'],
                    }
                    # Scenario 2, New Port
                    params.append({'delta_flag':'NEW_PORT', 'delta_description':'New Port Discovered on %s' % (datestamp,), 'fqdn_id':port['fqdn_id'], 'interface_id':port['interface_id']})
                else:
                    if history_tracking[identifier]['part_number'] != port['part_number']:
                        # Scenario 3, Optic Change
                        params.append({'delta_flag':'SOURCE_OPTIC_CHANGE', 'delta_description':'Slotted Optic Changed From %s to %s on %s' % (history_tracking[identifier]['part_number'], port['part_number'], datestamp), 'fqdn_id':port['fqdn_id'], 'interface_id':port['interface_id']})
                    elif history_tracking[identifier]['replacement_part_number'] != port['replacement_part_number']:
                        # Scenario 1, Map Change
                        params.append({'delta_flag':'MAPPING_CHANGE', 'delta_description':'Mapped Optic Changed From %s to %s on %s' % (history_tracking[identifier]['replacement_part_number'], port['replacement_part_number'], datestamp), 'fqdn_id':port['fqdn_id'], 'interface_id':port['interface_id']})
                    history_tracking[identifier] = {
                        'part_number': port['part_number'],
                        'replacement_part_number': port['replacement_part_number'],
                    }
    #update_deltas(cursor, params)
    #update_deltas_new(cursor, params)
    update_deltas_final(matrx_iom_utils, params)
    #update_deltas_with_execute(cursor, params)

