def format_part_number(pn):
    # Ensure part nubmers are properly stripped and remove the appended '(new)' from Suhas' data
    new_pn = None
    if pn is None:
        new_pn = None
    elif pn == 'NA':
        new_pn = None
    elif pn == 'n/a':
        new_pn = None
    elif '(new)' in pn:
        new_pn = pn.replace('(new)', '').strip()
    else:
        new_pn = pn.strip()

    if not pn:
        new_pn = None

    if type(new_pn) is str:
        new_pn = helpers.clean_text(new_pn)

    return new_pn

