def recommendation_pos(self, recomm_parts, boms_remains, ind_array, bom_id):
    try:
        for parts_recomm in recomm_parts:
            if parts_recomm['recommendation_type'] == 'individual':
                if boms_remains['component_name'] in parts_recomm['components'][0]['eqs']:
                    if parts_recomm['recommendation'][0]['yet_to_arrive'] == 0:
                        to_be_added = boms_remains['bom_part_count'] - boms_remains['qty_added']
                        for reco in parts_recomm.get('recommendation', []):
                            # echo "AvailLoose ".$reco['AvailLoose'];
                            if reco['AvailLoose'] > 0:
                                if to_be_added >= reco['AvailLoose']:
                                    to_be_added = to_be_added - reco['AvailLoose']
                                    added_qty = reco['AvailLoose']
                                elif to_be_added < reco['AvailLoose']:
                                    added_qty = to_be_added
                                    to_be_added = 0
                                else:
                                    added_qty = 0
                                    to_be_added = 0

                                if added_qty > 0:
                                    eqs = '","'.join([f'"{eq}"' for eq in reco['eqs']])

                                    data_remaining_bom_parts = self.update_shortage_array(data_remaining_bom_parts, boms_remains['component_name'], bom_id, added_qty)
                                    boms_remains['qty_added'] = boms_remains['qty_added'] + added_qty
                                    update_query = "UPDATE bom_database.bom_parts_shortage set qty_added=qty_added+? where bom_id=? and component_name IN (%s)" % eqs

                                    query(update_query, added_qty, bom_id, eqs)

                                    query = f"INSERT INTO `bom_database`.`auto_wo_log`(`bom_id`,`model_name`,`avail`,`component_number`,`bom_part_count`,`added_qty`,`pop`) VALUES ({bom_id},{reco['model_name']},{reco['AvailLoose']},{reco['component_number']},{boms_remains['bom_part_count']},{added_qty},{reco['pop']})"

                                    self.iom_utils.run_query(query, "INSERT")

                                    ind = {'model_name': reco['modelName'], 'added_qty': added_qty, 'po': reco['pop']}
                                    ind_array = self.update_ind_array(ind_array, reco['pop'], reco['modelName'], added_qty)

        return ind_array
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")

