        master_ids = []
        query = f"""
            SELECT bps.*,group_concat(distinct(IF(pb.po_number,pb.po_number, IF(pbb.po_number, pbb.po_number , '')))) as po,
                IF(threshold_count,threshold_count,0) as threshold_count
            from bom_database.bom_parts_shortage bps
            LEFT JOIN cifa.bom_threshold_detail btd ON btd.bom_id = bps.bom_id and bps.component_name = btd.component_number
