            group by bps.bom_id,btd.threshold_bom_id, bps.component_name
        """
        data_remaining_bom_parts = self.iom_utils.run_query(query, "SELECT")
        is_master_loop_break = False

        for master_id, parts_recomm_master in master_array.items():
            check_all_master_usage = 20
            back_up_master = parts_recomm_master
            is_valid_master = False
            if not parts_recomm_master:
                check_all_master_usage = 99
            for master in parts_recomm_master:
                each_check = 0
                for boms_remains in data_remaining_bom_parts:
                    if boms_remains['component_name'] == '3HE13343AA':
                        boms_remains['master_qty'] = master['qtyOnHand']
                        boms_remains['qtyOnHand_test'] = master['qtyOnHand'] + boms_remains['qty_added']
                        boms_remains['master_id'] = master_id

                    pos = []
                    if boms_remains['po']:
                        pos = boms_remains['po'].split(",")
                    else:
                        pos.append(each_po['pop'])

                    if not pos:
                        if boms_remains['component_name'] in master['eqs']:
                            if (master['qtyOnHand'] + boms_remains['qty_added']) <= boms_remains['bom_part_count']:
                                is_valid_master = True
                                each_check = 1
                    else:
                        for po in pos:
                            if po in po_master_array and master_id in po_master_array[po]:
                                if boms_remains['component_name'] in master['eqs']:
                                    if boms_remains['threshold_count'] > 0 and boms_remains['threshold_count'] != boms_remains['bom_part_count']:
                                        if (master['qtyOnHand'] + boms_remains['qty_added']) <= boms_remains['threshold_count']:
                                            is_valid_master = True
                                            each_check = 1
                                    else:
                                        if (master['qtyOnHand'] + boms_remains['qty_added']) <= boms_remains['bom_part_count']:
                                            is_valid_master = True
                                            each_check = 1

                if each_check == 0:
                    check_all_master_usage = 99
                    verify_kitted = self.check_master_kitted(master['eqs'])
                    if not verify_kitted:
                        is_valid_master = False
                    if verify_kitted and is_valid_master:
                        check_all_master_usage = 20

            if check_all_master_usage == 20:
                if is_valid_master:
                    for master_insert in back_up_master:
                        for key, boms_remains in enumerate(data_remaining_bom_parts):
                            if boms_remains['component_name'] in master_insert['eqs']:
                                data_remaining_bom_parts[key]['qty_added'] += master_insert['qtyOnHand']
                                update_query = f"""
                                    UPDATE bom_database.bom_parts_shortage
                                    set qty_added=qty_added+{master_insert['qtyOnHand']}
                                    where bom_id={bom_id} and component_name = {boms_remains['component_name']}
                                """
                                self.iom_utils.run_query(update_query, "UPDATE")
                                master_insert['qtyOnHand'] = 0
                    master_ids.append(master_id)
                if is_master_loop_break:
                    break
            return master_ids
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")

