def check_po_status(self, po_items):
    try:
        counter = 0
        del_check = 0

        total_po_ordered_qty = sum(item['quantity'] if item['quantity'] is not None else 0 for item in po_items)
        if total_po_ordered_qty < 1:
            return

        for item in po_items:
            toReceived = item['totReceived']
            if item['totReceived'] is None:
                toReceived = 0
            quantity = item['quantity']
            if item['quantity'] is None:
                quantity = 0
            if toReceived < quantity:
                counter = 1
            del_check = 1

        if counter == 0 and del_check == 1:
            self.mark_bom_as_landed(po_items[0]['po_number'])
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")

