def get_kibana_link(uuid, index, dashboard_url, start_time, end_time, level=None):
    kibana_link = None
    try:
        if level:
            search_string = f'uuid : {uuid} and level : "ERROR" '
        else:
            search_string = f'uuid : {uuid} '

        search_string = Kibana.encode_string(search_string)

        kibana_link = f"""{dashboard_url}#/?_g=(filters:!(),refreshInterval:(pause:!t,value:60000),time:(from:'{start_time}',to:'{end_time}'))&_a=(columns:!(script_name,message,level,owner,uuid),filters:!(),index:'{index}*',interval:auto,query:(language:kuery,query:'{search_string}'),sort:!(!('@timestamp',desc)))"""

    except Exception as e:
