def fetch_mod_log(self, payload):
    response = {}
    try:
        query_json = {
            "query": [{
                "WOPrefix_Number": payload.get('wo_number')
            }]
        }
        query_str = json.dumps(query_json)
        print(f"Query String: {query_str}")
        url = f"https://filemaker.cable.comcast.com/fmi/data/v1/databases/ComcastOne/layouts/API_WOModLog/_find"
        self.file_maker_api = FileMakerAPI(iom_utils=self.iom_utils, IomUtils=IomUtils)
        headers = {
            'Accept': 'application/json',
            'Authorization': f'Bearer {self.file_maker_api.token}',
            'Content-Type': 'application/json'
        }
        response_obj = requests.post(url, headers=headers, data=query_str, verify=False)
        response_json = response_obj.json()

        if response_json['response']['dataInfo']['foundCount'] > 0:
            data = response_json['response']['data']
            if data:
                field_data = data[0].get('fieldData', {})
                zModLog = field_data.get('zModLog', "")
                augment_plan = None
                for line in zModLog.split('\r'):
                    if 'AugmentPlan' in line:
                        parts = line.split('\t')
                        for part in parts:
                            if part.startswith('AugmentPlan'):
                                augment_plan = parts[-1].split('»')[-1].strip()
                                break
                    if augment_plan:
                        break
                response['augment_plan'] = augment_plan
                response['status'] = True
                message = "Rack status has been updated successfully."
            else:
                response['status'] = False
                message = "No data found."
        else:
            response['status'] = False
            message = "Rack status update was not successful."

    except Exception as e:
        print(f"Exception occurred: {e}, {traceback.format_exc()}")
        response['status'] = False
        response['message'] = str(e)
    return response

