get_response.code:
def get_response(self, api_name, method="POST", headers=None, params=None, payload=None, retry=0):
    status = False
    response_json = {}
    try:

        payload = payload if payload else {}
        self.token = self.token_generator.get_token(True)

        params = params if params else {"WSDL": ""}
        headers = headers if headers else {'Content-Type': 'application/json'}
        headers['Authorization'] = f"""Bearer {self.token}"""
        headers['Accept'] = 'application/json'
        logger.debug(f"URL: {self.url}")
        logger.debug(f"Params: {params}")
        logger.debug(f"Headers: {headers}")
        logger.debug(f"Payload: {payload}")
        response = requests.request(method=method, url=self.url, headers=headers, data=dumps(payload))
        self.hit_count += 1
        logger.debug(f"Remaining: {self.count}")
        self.count -= 1  
        if response.status_code == 200 and response.json().get('STATUS') == 'SUCCESS' and len(response.json().get('ROW', [])) > 0:
            response_json = response.json().get('ROW', [])[0].get('TRANSACTION_DATA', {}) if len(response.json().get('ROW')) > 0 else {}
            response_time = response.elapsed.total_seconds()
            logger.debug(f"Successful response for service: {api_name}, response_time: {response_time}, hit_count: {self.hit_count}")
            status = True
        elif retry < 2:
            sleep(2)
            logger.debug(f"Retry: {retry} after 2 seconds")
            return self.get_response(api_name, method, headers, params, payload, retry=retry + 1)
        else:
            logger.debug(response.json())
            logger.debug(f"Unsuccessful response for service: {api_name}, status code: {response.status_code}, hit_count: {self.hit_count}")
    except Exception as e:
        exception_name = type(e).__name__
        logger.exception(f"Exception ({exception_name}) occurred in service {api_name}: {traceback.format_exc()}")
        if retry < 2:
            sleep(2)
            logger.exception(f"Exception - Retry: {retry} after 2 seconds")
            return self.get_response(api_name, method, headers, params, payload, retry=retry + 1)
        else:
            self.exception_list.append(
                {
                    'url': self.url,
                    'params': params,
                    'headers': headers,
                    'payload': payload,
                    'api_name': api_name,
                    'method': method,
                    'timestamp': datetime.now().strftime('%Y-%m-%d %I:%M:%S %p'),
                    'exception_name': exception_name
                }
            )
    return status, response_json

