def calculate_need_by_date(self, month, year):
    try:
        current_month = month
        current_year = year

        if 1 <= current_month <= 3:
            start_date = datetime(current_year, 1, 1)
            end_date = datetime(current_year, 4, 1)
        elif 4 <= current_month <= 6:
            start_date = datetime(current_year, 4, 1)
            end_date = datetime(current_year, 7, 1)
        elif 7 <= current_month <= 9:
            start_date = datetime(current_year, 7, 1)
            end_date = datetime(current_year, 10, 1)
        elif 10 <= current_month <= 12:
            start_date = datetime(current_year, 10, 1)
            end_date = datetime(current_year + 1, 1, 1)

        return start_date
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")

