getWorkingDays.code:
def getWorkingDays(self, startDate, endDate, holidays):
    if(self.parse_date(startDate) is None or self.parse_date(endDate) is None):
        return 0
    try:
        fmt = "%Y-%m-%d %H:%M:%S"
        date1 = datetime.strptime(str(startDate), fmt)
        date2 = datetime.strptime(str(endDate), fmt)

        d2 = date2.strftime('%s')
        d1 = date1.strftime('%s')
        days = (int(d2) - int(d1)) / 86400
        no_full_weeks = math.floor(days / 7)
        no_remaining_days = math.fmod(days, 7)
        the_first_day_of_week = date1.weekday()
        the_last_day_of_week = date2.weekday()
        if the_first_day_of_week <= the_last_day_of_week:
            if the_first_day_of_week <= 5 and 5 <= the_last_day_of_week:
                no_remaining_days = no_remaining_days - 1
            if the_first_day_of_week <= 6 and 6 <= the_last_day_of_week:
                no_remaining_days = no_remaining_days - 1
        else:
            if the_first_day_of_week == 6:
                no_remaining_days = no_remaining_days - 1
                if the_last_day_of_week == 5:
                    no_remaining_days = no_remaining_days - 1
            else:
                no_remaining_days = no_remaining_days - 2
        workingDays = no_full_weeks * 5
        if no_remaining_days > 0:
            workingDays += no_remaining_days
        for holiday in holidays:
            holiday_datetime = datetime.combine(holiday, datetime.min.time())
            time_stamp = holiday_datetime.strftime('%s')
            time_stamp_date = datetime.strptime(str(holiday), fmt)
            if d1 <= time_stamp and time_stamp <= d2 and time_stamp_date.weekday() != 5 and time_stamp_date.weekday() != 6:
                workingDays = workingDays - 1
        total_sec = workingDays * 24 * 60 * 60
        day = total_sec // (24 * 3600)
        time = total_sec % (24 * 3600)
        hour = time // 3600
        time %= 3600
        minutes = time // 60
        time %= 60
        seconds = time
        if day < 0:
            day = 0
            hour = 0

        return ("%d.%d" % (day, hour))
    except Exception as e:
        logger.exception(f"Exception: {e}, {traceback.format_exc()}")

