class IomUtils:
    def __init__(self, db_name=None, schema_name=None):
        self.db_name = db_name if db_name else "bom_db"
        self.schema_name = schema_name if schema_name else "filemaker"
        self.conn = self.cursor = None
        self.connect_database()
        self.model_dict = {}
        self.status_dict = {}
        self.manufacturer_dict = {}
        self.cifa_dict = {}
        self.rack_dict = {}
        self.disposition_dict = {}
        self.wo_step_dict = {}
        self.requestor_dict = {}
        self.dns_dict = {}
        self.contact_dict = {}
        self.ship_dict = {}
        self.address_dict = {}
        self.users_dict = {}
        self.supplier_dict = {}
        self.get_script_owner()

    def connect_database(self):
        try:
            self.conn, self.cursor = database.mysql_con(self.db_name)
        except Exception as e:
            logger.exception(f"Exception occurred in connect_database: {e}, {traceback.format_exc()}")

    def __del__(self):
        self.cursor.close()
        self.conn.close()
        logger.debug(f"Closed database: {self.db_name} connection")

    def get_script_owner(self):
        try:
            global script_owner, script_id
            if not script_owner and not script_id:
                file_name = path.basename(sys.argv[0])
                file_path = path.abspath(sys.argv[0])
                query = f"SELECT creator, id FROM matrix.script_stamp WHERE file_name = '{file_name}'"
                result = self.run_query(query, "SELECT")
                if result:
                    script_owner = result[0]['creator']
                    script_id = result[0]['id']
                else:
                    query = f"INSERT INTO matrix.script_stamp (file_name, stamp, active, script_name) VALUES ('{file_name}', NOW(), 0, '{file_path}');"
                    script_id = self.run_query(query, "INSERT")
        except Exception as e:
            logger.exception(f"Exception occurred in get_script_owner: {e}, {traceback.format_exc()}")

    def run_query(self, query, query_type='', values=None, bulk_insert=False, insert_no_auto_increment=False, retry=0) -> any:
        result = None
        try:
            if query_type == "SELECT":
                logger.debug(f"Query: {query}")
                if values:
                    logger.debug(f"Values: {values}")
                self.cursor.execute(query, values)
                result = self.cursor.fetchall()
            elif query_type == "INSERT":
                if values:
                    if len(values) == 1:
                        logger.debug(f"Query: {query}")
                        logger.debug(f"Values: {values}")
                        self.cursor.execute(query, values[0])
                        if self.cursor.rowcount > 0:
                            result = self.cursor.lastrowid
                        if insert_no_auto_increment:
                            result = True
                    else:
                        self.cursor.executemany(query, values)
                        result = True
                else:
                    logger.debug(f"Query: {query}")
                    self.cursor.execute(query)
                    if self.cursor.rowcount > 0:
                        result = self.cursor.lastrowid
                    if insert_no_auto_increment or bulk_insert:
                        result = True
            else:
                if query_type in ("UPDATE", "DELETE"):
                    self.cursor.execute("SET SQL_SAFE_UPDATES = 0")
                    if values:
                        self.cursor.executemany(query, values)
                    else:
                        logger.debug(f"Query: {query}")
                        self.cursor.execute(query)
                    result = True
                else:
                    self.cursor.execute(query)
                    result = True
        except mysql.connector.Error as e:
            logger.exception(f"Query: {query}")
            logger.exception(f"Values: {values}")
            logger.exception(f"mysql.connector error in run_query: {e}")
            if e.errno in (1213,2006, 2013, 3100, 1290,1205) and retry < 3:
                retry += 1
                logger.warning(f"Connection lost, retry: {retry} after 10 seconds")
                sleep(10)
                self.connect_database()
                return self.run_query(query, query_type, values, bulk_insert, insert_no_auto_increment, retry)
        except MySQLdb.Error as e:
            logger.exception(f"Query: {query}")
            logger.exception(f"Values: {values}")
            logger.exception(f"MySQLdb error in run_query: {e}")
            if e.args[0] in (1213, 2006, 2013, 3100, 1290, 1205) and retry < 3:
                retry += 1
                logger.warning(f"Connection lost, retry: {retry} after 10 seconds")
                sleep(10)
                self.connect_database()
                return self.run_query(query, query_type, values, bulk_insert, insert_no_auto_increment, retry)
        return result

    def get_db_and_server_time(self):
        db_date_time = server_date_time = None
        try:
            result = self.run_query("SELECT DATE_FORMAT(NOW(), '%Y-%m-%d %h:%i:%s %p') AS date_time;", "SELECT")
            if result:
                db_date_time = datetime.strptime(result[0].get('date_time'), '%Y-%m-%d %I:%M:%S %p')
                server_date_time = datetime.strptime(datetime.now().strftime('%Y-%m-%d %I:%M:%S %p'), '%Y-%m-%d %I:%M:%S %p')
                logger.debug(f"Database date_time: {db_date_time}")
                logger.debug(f"Server date_time: {server_date_time}")
        except Exception as e:
            logger.exception(f"Exception occurred in get_db_and_server_time: {e}, {e}, {traceback.format_exc()}")
        return db_date_time, server_date_time

    def insert_data(self, insert_list, table_name, truncate=False, limit=10000, ignore=True, update_columns=None, insert_no_auto_increment=True, ignore_by_colomun=False, duplicate_command=True):
        insert_result = 0
        duplicate_count = unique_count = None
        try:
            count = int(ceil(len(insert_list) / limit))
            if truncate:
                query = f"TRUNCATE {table_name}"
                logger.debug(f"Query: {query}")
                self.run_query(query, "TRUNCATE")
            insert_list, duplicate_count, unique_count = self.remove_duplicate_dicts(insert_list)
            ignore = 'IGNORE' if ignore else ''
            for start_index in range(0, len(insert_list), limit):
                end_index = start_index + limit
                chunk = insert_list[start_index:end_index]

                columns = list(insert_list[0].keys())
                update_columns = update_columns if update_columns else {}
                columns.extend(update_columns.keys())
                columns = [f"`{column}`" for column in columns]
                placeholders = ', '.join(['%s'] * len(columns))
                query = f"INSERT {ignore} INTO {table_name} ({', '.join(columns)}) VALUES ({placeholders})"
                on_duplicate_clause = ', '.join([f'{col} = VALUES({col})' for col in columns])
                if (duplicate_command):
                    query += f" ON DUPLICATE KEY UPDATE {on_duplicate_clause}"

                if (ignore_by_colomun):
                    placeholders = ', '.join([f'%s' for col in columns])
                    query = f"INSERT  INTO {table_name} ({', '.join(columns)}) SELECT {placeholders}"

                    on_duplicate_clause_rows = ' AND  '.join([f'{col} = %s' for col in columns])
                    query += f" WHERE NOT EXISTS ( SELECT 1 FROM {table_name}  WHERE {on_duplicate_clause_rows}); "
                    values_list = [
                        tuple({**data, **update_columns}[col.replace('`', '')] for col in columns) +
                        tuple({**data, **update_columns}[col.replace('`', '')] for col in columns)
                        for data in chunk
                    ]
                else:
                    values_list = [tuple({**data, **update_columns}[col.replace('`', '')] for col in columns) for data in chunk]
                result = self.run_query(query, 'INSERT', values_list, insert_no_auto_increment=insert_no_auto_increment)
                if result:
                    insert_result = insert_result + len(chunk)
                    logger.debug(f"{count} - Inserted {len(chunk)} records into {table_name}")
                else:
                    logger.debug(f"{count} - {len(chunk)} records are not inserted into {table_name}")
                count = count - 1
        except Exception as e:
            logger.exception(f"Exception occurred in insert_data: {e}, {traceback.format_exc()}")
        return insert_result, duplicate_count, unique_count

    def insert_single_record(self, insert_dict, table_name):
        insert_id = 0
        try:
            columns = ', '.join(insert_dict.keys())
            values = ', '.join(['%s'] * len(insert_dict))
            query = f"INSERT INTO {table_name} ({columns}) VALUES ({values})"
            on_duplicate_clause = ', '.join([f"{col} = VALUES({col})" for col in insert_dict.keys()])
            query += f" ON DUPLICATE KEY UPDATE {on_duplicate_clause}"
            insert_id = self.run_query(query, 'INSERT', [tuple(insert_dict.values())])
        except Exception as e:
            logger.exception(f"Exception occurred in insert_single_record: {e}, {traceback.format_exc()}")
        return insert_id

    @staticmethod
    def remove_duplicate_dicts(duplicate_list):
        unique_list = []
        duplicate_count = unique_count = None
        try:
            duplicate_count = len(duplicate_list)
            logger.debug(f"duplicate_list: {duplicate_count}")
            seen = set()
            for d in duplicate_list:
                if(type(d) is not list and type(d) is not tuple):
                    t = tuple(sorted(d.items()))
                    if t not in seen:
                        seen.add(t)
                        unique_list.append(d)
            unique_count = len(unique_list)
            logger.debug(f"unique_list: {unique_count}")
        except Exception as e:
            logger.exception(f"Exception occurred in remove_duplicate_dicts: {e}, {traceback.format_exc()}")
        return unique_list, duplicate_count, unique_count

    def calculate_run_time(self, start_time, end_time, table=None, result=None, comment=None):
        try:
            result = dumps(result).replace("'", " ") if result else {}
            time_difference = end_time - start_time
            days = time_difference.days
            seconds = time_difference.seconds
            hours, remainder = divmod(seconds, 3600)
            minutes, seconds = divmod(remainder, 60)
            run_time = f'{days} days {hours} hours {minutes} minutes {seconds} seconds'
            if table:
                query = f"""
                    INSERT INTO filemaker.log (`table`, `runTime`, `result`, `comment`)
                    VALUES ('{table}', '{run_time}', '{result}', '{comment}');
                    """
                self.run_query(query, "INSERT")

            logger.debug(f"Start time: {start_time.strftime('%Y-%m-%d %I:%M:%S %p')}")
            logger.debug(f"End time: {end_time.strftime('%Y-%m-%d %I:%M:%S %p')}")
            logger.debug(f"Run time: {run_time}")
        except Exception as e:
            logger.exception(f"Exception occurred in calculate_run_time ", traceback.format_exc())

    def check_file_transfer_status(self, table_name, file_path, retry=1, hours=1):
        try:
            email_data = {}
            db_date_time, server_date_time = self.get_db_and_server_time()

            email_data['Table Name'] = table_name
            email_data['File Path'] = file_path
            email_data['Database Date Time'] = db_date_time
            email_data['Server Date Time'] = server_date_time

            try:
                sleep(10)
                file_created_date_time = datetime.utcfromtimestamp(path.getctime(file_path))
                logger.debug(f"file_created_date_time: {file_created_date_time}")

            except Exception as e:
                if e.errno == 13:
                    message = f"Exception: Permission denied for the file at path: {file_path}"
                    logger.exception(message)
                elif e.errno == 2:
                    message = f"Exception: File not found at the path: {file_path}"
                    logger.exception(message)
                else:
                    message = f"Exception while getting the file from path: {file_path} with errno: {e.errno}"
                    logger.exception(message)
                email_data['Subject'] = '[Filemaker] import delay: %s' % message
                email_data['Message'] = message
                status, message = IomUtils.send_email_from_api(email_data)
                logger.debug(f"Email status: {status}, message: {message}")
                return False

            if server_date_time.date() == file_created_date_time.date() and file_created_date_time < server_date_time:
                logger.debug("File is transferred to server and script will execute now")
                return True
            else:
                message = "File is not transferred to the server"
                logger.debug(f"{message}, retry: {retry}, hour(s): {hours}")
                if retry % 12 == 0:
                    email_data['Message'] = message
                    email_data['Delayed Time'] = f"{hours} hour(s)"
                    email_data['Subject'] = f'[Filemaker] import delay: {hours} hour(s)'
                    # Send email for every 1 hour for next 12 hours.
                    status, message = IomUtils.send_email_from_api(email_data)
                    logger.debug(f"Email status: {status}, message: {message}")
                    if hours == 12:
                        return False
                    hours += 1
                # Sleep for 5 minutes.
                sleep(300)
                return self.check_file_transfer_status(table_name, file_path, retry + 1, hours)
        except Exception as e:
            logger.exception(f"Exception occurred in check_file_transfer_status: {e}, {traceback.format_exc()}")

