                    for data in result:
                        if data.get('contactEmail'):
                            self.contact_dict[str(data.get('contactEmail')).strip().lower()] = data.get('contactId')
                except Exception as e:
                    logger.exception(f"Exception occurred in get_contact: {e}, {traceback.format_exc()}")
            if contact_email:
                contact_email = sub(r"['\"=]", '', contact_email)
                contact_email = (sub(r'[^\x20-\x7E]', '', contact_email)).strip()
                valid_emails = findall(r'[\w\.-]+@[\w\.-]+\.\w{2,}', contact_email) if contact_email else []
                for valid_email in valid_emails:
                    contact_id = self.contact_dict.get(valid_email.strip().lower()) if valid_email else None
                    if contact_id:
                        break
                    else:
                        continue
                if not contact_id and valid_emails:
                    for valid_email in valid_emails:
                        query = f'select contactId from {table_name} where lower(trim(contactEmail)) = "{valid_email.strip().lower()}";'
                        result = self.run_query(query, 'SELECT')
                        if result:
                            contact_id = result[0].get('contactId')
                            if contact_id:
                                break
                            else:
                                continue
                    if not contact_id:
                        contact_phone = sub(r'\D', '', contact_phone) if contact_phone else None
                        contact_phone = self.get_numeric_value(contact_phone, value_range="bigint")
                        contact_phone = contact_phone if contact_phone else 0
                        contact_name = sub(r"[-\t\n\r.,\"'-]", ' ', contact_name)
                        contact_name = (sub(r'[^\x20-\x7E]', '', contact_name)).strip()
                        contact_name = contact_name if contact_name else None
                        query = f'insert into {table_name} (contactName, contactEmail, contactPhone) values ("{contact_name}","{valid_emails[0]}","{contact_phone}");'
                        contact_id = self.run_query(query, 'INSERT')
                        if contact_id:
                            self.contact_dict[valid_emails[0].strip().lower()] = contact_id
        except Exception as e:
            logger.exception(f"Exception occurred in get_contact_id: {e}, {traceback.format_exc()}")
        return contact_id

