    def get_pagination_result(self, query, result_list=None, offset=0, limit=100000):
        try:
            result_list = result_list if result_list else []
            result = self.run_query(f"{query} LIMIT {offset}, {limit};", "SELECT")
            if result:
                result_list.extend(result)
                if len(result) == limit:
                    self.get_pagination_result(query, result_list, offset + limit)
                    offset += limit
            logger.debug(f"Pagination count: {len(result_list)}")
        except Exception as e:
            logger.exception(f"Exception occurred in get_pagination_result: {e}, {traceback.format_exc()}")
        return result_list

    def update_query_pagination(self, query, record_ids, message, limit=1000):
        status = False
        try:
            result_list = []
            count = int(ceil(len(record_ids) / limit))
            for start_index in range(0, len(record_ids), limit):
                end_index = start_index + limit
                chunk = record_ids[start_index:end_index]
                ids = ','.join([f'"{str(item)}"' for item in chunk])
                result = self.run_query(query % ids, "UPDATE")
                if result:
                    logger.debug(f"{count} - Success - {message}")
                else:
                    logger.debug(f"{count} - Fail - {message}")
                count -= 1
                result_list.append(result)
            result_set = list(set(result_list))
            if len(result_set) == 1 and result_set[0]:
                status = True
            else:
                logger.debug("Update is not successful")
        except Exception as e:
            logger.exception(f"Exception occurred in update_query_pagination: {e}, {traceback.format_exc()}")
        return status

    def select_and_update(self, select_query, update_query, insert_result, comment):
        status = False
        try:
            results = self.get_pagination_result(select_query)
            ids = [result.get('id') for result in results]
            logger.debug(f"Select query result: {len(ids)}")
            if ids:
                status = self.update_query_pagination(update_query, ids, comment)
            else:
                insert_result[f"{comment} message"] = "No data found to update"
        except Exception as e:
            logger.exception(f"Exception occurred in select_and_update: {e}, {traceback.format_exc()}")
        insert_result[comment] = status
        return insert_result

