    @staticmethod
    def get_quarters_from_start_date(start_date_str):
        quarter_dates = []
        try:
            if start_date_str:
                start_flag = False

                start_date = datetime.strptime(start_date_str, "%Y-%m-%d").date()
                current_date = datetime.now().date()

                while start_date <= current_date:
                    quarter_start_month = ((start_date.month - 1) // 3) * 3 + 1

                    if not start_flag:
                        quarter_start = start_date
                        start_flag = True
                    else:
                        quarter_start = date(start_date.year, quarter_start_month, start_date.day)

                    last_day_of_month = calendar.monthrange(start_date.year, quarter_start_month + 2)[1]
                    quarter_end = date(start_date.year, quarter_start_month + 2, last_day_of_month)
                    quarter_end = min(quarter_end, current_date)

                    quarter_dates.append(
                        {
                            "quarter": f"{quarter_start.year}Q{((quarter_start.month - 1) // 3) + 1}",
                            "current_date": current_date.strftime("%Y-%m-%d"),
                            "start_date": quarter_start.strftime("%Y-%m-%d"),
                            "end_date": quarter_end.strftime("%Y-%m-%d")
                        })
                    start_date = quarter_end + timedelta(days=1)
        except Exception as e:
            logger.exception(f"Exception occurred in get_quarters_from_start_date: {e}, {traceback.format_exc()}")
        return quarter_dates

    @staticmethod
    def get_quarter_start_date(given_date):
        quarter_start_date = None
        try:
            given_date = datetime.strptime(given_date, "%Y-%m-%d").date()
            month = given_date.month
            year = given_date.year
            quarter_start_month = ((month - 1) // 3) * 3 + 1
            quarter_start_date = date(year, quarter_start_month, 1)
        except Exception as e:
            logger.exception(f"Exception occurred in get_quarter_start_date: {e}, {traceback.format_exc()}")
        return quarter_start_date

    """
    #fields = {'last_update': '2024-03-01 14:01:42', 'one_time_update': 1, 'run_counter': 4, 'one_time_update_time' : '2024-03-01 14:01:42'}
    """

    def update_script_stamp(self, script_id, execution, fields={}, allowedBuffTime=0, maxBuffAllowTime=0):
        execute = False
        try:
            updateFields = ''
            if fields:
                for dbField, dbValue in fields.items():
                    updateFields += f", {dbField} = '{dbValue}' "

            # Set the timezone to "America/New_York"
            eastern = pytz.timezone('America/New_York')
            currUSTime = datetime.now(eastern).replace(tzinfo=None)
            if execution == 'start':
                query = f"SELECT * from filemaker2.script_stamp_status WHERE script_id = {script_id};"
                current_status = self.run_query(query, "SELECT")
                logger.debug(f"Query result: {current_status[0]}")
                execute = True
                if current_status[0]['completion_status'] == 2:
                    execute = True
                if current_status[0]['completion_status'] != 1 and current_status[0]['completion_status'] != 2:
                    lastExeDateTime = current_status[0]['last_run']
                    lastRunPlusAllowedBuff = lastExeDateTime + timedelta(hours=allowedBuffTime)
                    lastRunPlusMaxBuff = lastExeDateTime + timedelta(hours=maxBuffAllowTime)

                    # Make lastRunPlusAllowedBuff timezone-aware by converting it to the "America/New_York" timezone
                    lastRunPlusAllowedBuff = lastRunPlusAllowedBuff.replace(tzinfo=None)

                    if (currUSTime > lastRunPlusAllowedBuff) and (currUSTime < lastRunPlusMaxBuff or maxBuffAllowTime == 0):
                        execute = True
                    else:
                        execute = False

                if execute == True:
                    query = f"UPDATE filemaker2.script_stamp_status SET completion_status = 0 WHERE script_id = {script_id};"
                    self.run_query(query, "UPDATE")

            if execution == 'complete':
                query = f"UPDATE filemaker2.script_stamp_status SET completion_status = 1, last_run = '{currUSTime}' {updateFields} WHERE script_id = {script_id};"
                self.run_query(query, "UPDATE")
                execute = True
            if execution == 'error':
                query = f"UPDATE filemaker2.script_stamp_status SET completion_status = 2, last_run = '{currUSTime}' {updateFields} WHERE script_id = {script_id};"
                self.run_query(query, "UPDATE")
                execute = True
        except Exception as e:
            logger.exception(f"Exception occurred in wo scheduler: {e}, {traceback.format_exc()}")
            execute = False
        return execute

