                    <h2>Detailed Results</h2>
                    {self._generate_script_result_html(self.results)}
                </div>
            </div> 
        </body>
        </html>
        """
        return html_content

    def _generate_script_result_html(self, result):
        if(result):
            print("result")
            print(result)
            print("result")
            status_class = 'script-success' if result.get('status') == 'completed' else 'script-failed'
            issue_type = ' - '
            if (result.get('issue') == "data_issue"):
                issue_type = "Business"                
            if (result.get('issue') != "data_issue" and result.get('status') != 'completed'):
                issue_type = "Technical"

            if(result.get('status') == 'completed'):
                status_text = f"""<p><strong>Status: </strong> Completed</p>"""
            else:
                status_text = f"""<p><strong>Status: </strong> Failed</p>"""
            return f"""
            <div class="script-result {status_class}">
                <h3>Class: {result.get('class')}</h3>
                <p><strong>Script: </strong>{path.basename(sys.argv[0])}</p>
                <p><strong>Script Owner:</strong> {result.get('script_owner')}</p>
                <p><strong>Exception Type :</strong> {issue_type}</p> 
                {status_text}
                </strong> {result.get('not_updated_data') if 'not_updated_data' in result else ' - '}</p>
            </div>
            """
        return ""

