            query = f"INSERT INTO `bom_database`.`de_proc_workflow_log`(`workflow_id`, `update_time`, `status`, `user_id`, `type`) VALUES ({workflow_id}, CURRENT_TIMESTAMP, {status}, {self.user_id}, {type_val})"
            self.results = self.iom_utils.run_query(query, "INSERT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def get_workflow_info_for_completion(self):
        try:
            query = """SELECT workflow_id as workflow_number,type from bom_database.de_proc_workflow where status=62
            """
            return self.iom_utils.run_query(query, "SELECT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def get_po_items_info(self, workflow_number):
        try:
            query = f"""SELECT pi.po_number, fm.poNumber, fm.CIFANumber, IF(fm.totReceived, fm.totReceived, 0) as totReceived, totShipped, pi.quantity FROM cifa.po_items pi LEFT JOIN cifa.po_workflow pw ON pw.po_number = pi.po_number JOIN cifa.preq_details pd ON pd.preq_number = pw.preq_number and pd.delete_flag = 0 and pd.status = 'APPROVED' LEFT JOIN cifa.fm_po_line fm ON fm.poNumber = pi.po_number AND fm.CIFANumber = pi.cifa_item_number WHERE pw.workflow_number ={workflow_number} and pd.preq_number is not null
            """
            return self.iom_utils.run_query(query, "SELECT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def move_to_wh_completed(self):
        try:
            fetch = self.get_workflow_info_for_completion()
            if fetch:
                for data in fetch:
                    workflow_number = data["workflow_number"]
                    po_items_info = self.get_po_items_info(workflow_number)
                    if po_items_info and any(
                            item["totShipped"] is not None
                            and item["totShipped"] < item["totReceived"]
                            for item in po_items_info
                    ):
                        self.update_workflow_and_notify(
