    def get_workflow_info_for_wh(self, workflow_number):
        try:
            query = f"""
                SELECT pw.workflow_number, GROUP_CONCAT(pw.po_number), w.type FROM cifa.po_workflow pw JOIN bom_database.de_proc_workflow w ON w.workflow_id = pw.workflow_number WHERE pw.workflow_number NOT IN (SELECT DISTINCT pw.workflow_number FROM cifa.po_workflow pw LEFT JOIN cifa.preq_details pd ON pd.preq_number = pw.preq_number AND pd.delete_flag = 1 WHERE pw.po_number = 0 AND pd.preq_number IS NULL) AND w.status = 59 GROUP BY pw.workflow_number
            """
