                        "INSERT")
                    self.iom_utils.run_query(f"INSERT INTO bom_database.logs (log_time, log_user, log_bom, log_text) VALUES(CURRENT_TIMESTAMP, '938', {bom_id}, 'Parent WO created.')", "INSERT")
