                    if bom_result:
                        for bom in bom_result:
                            wo = bom['woNumber']
                            unlock = UnlockWoHandler(self.iom_utils)
                            unlock.unlock_wo(wo)

                    query = f"""
                        SELECT pw.bom_id, u.user_login
                        FROM bom_database.boms pw
