                where bps.bom_id={bom_id} and bom_part_count>qty_added
                group by bps.bom_id,btd.threshold_bom_id, bps.component_name
            """
            data_remaining_bom_parts = self.iom_utils.run_query(query, "SELECT")
            is_master_loop_break = False

            for master_id, parts_recomm_master in master_array.items():
                check_all_master_usage = 20
