                                    if boms_remains['component_name'] in master['eqs']:
                                        if boms_remains['threshold_count'] > 0 and boms_remains['threshold_count'] != boms_remains['bom_part_count']:
                                            if (master['qtyOnHand'] + boms_remains['qty_added']) <= boms_remains['threshold_count']:
                                                is_valid_master = True
                                                each_check = 1
                                        else:
                                            if (master['qtyOnHand'] + boms_remains['qty_added']) <= boms_remains['bom_part_count']:
                                                is_valid_master = True
                                                each_check = 1

                    if each_check == 0:
                        check_all_master_usage = 99
                        verify_kitted = self.check_master_kitted(master['eqs'])
                        if not verify_kitted:
                            is_valid_master = False
                        if verify_kitted and is_valid_master:
                            check_all_master_usage = 20

                if check_all_master_usage == 20:
                    if is_valid_master:
                        for master_insert in back_up_master:
                            for key, boms_remains in enumerate(data_remaining_bom_parts):
                                if boms_remains['component_name'] in master_insert['eqs']:
                                    data_remaining_bom_parts[key]['qty_added'] += master_insert['qtyOnHand']
