class PoLand:
    def __init__(self):
        self.iom_utils = IomUtils()
        util.start()
        self.po_land()

    def mark_bom_as_landed(self, po_number):
        try:
            query = f"""
                SELECT 
                    CURRENT_TIMESTAMP AS log_time, 
                    938 as log_user, 
                    pobom.bom_number as log_bom, 
                    pobom.po_number as po_number
                FROM cifa.po_bom pobom 
                WHERE pobom.po_number = {po_number};
            """
            res = self.iom_utils.run_query(query, "SELECT")
            for r in res:
                payload = {
                    "user": 938,
                    "bom": r['log_bom'],
                    "text": f"""PO:<a href='/matrix/neteng/finance/po-view.php?id={r['po_number']}' target='_blank'>{r['po_number']}</a>is 100% landed in warehouse"""
                }
                requests.post(f"{icputils.config.env_configs.get('api_url')}/api/logs/bom_update_status", json=payload, verify=False)
            # self.results = self.iom_utils.run_query(log_query)

            po_landed_query = f"INSERT INTO bom_database.po_landed (po_number) VALUES ({po_number})"

            self.iom_utils.run_query(po_landed_query, "INSERT")
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def check_po_status(self, po_items):
        try:
            counter = 0
            del_check = 0

            total_po_ordered_qty = sum(item['quantity'] if item['quantity'] is not None else 0 for item in po_items)
            if total_po_ordered_qty < 1:
                return

            for item in po_items:
                toReceived = item['totReceived']
                if item['totReceived'] is None:
                    toReceived = 0
                quantity = item['quantity']
                if item['quantity'] is None:
                    quantity = 0
                if toReceived < quantity:
                    counter = 1
                del_check = 1

            if counter == 0 and del_check == 1:
                self.mark_bom_as_landed(po_items[0]['po_number'])
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

    def po_land(self):
        try:
            query = """
                   SELECT pb.po_number FROM cifa.po_bom pb JOIN bom_database.boms b ON b.bom_id = pb.bom_number JOIN cifa.preq_details pd ON pd.preq_number = pb.preq_number and pd.status='Approved' and pd.delete_flag=0 JOIN cifa.po_details pod ON pod.po_number = pb.po_number and pod.po_status='Approved' LEFT JOIN cifa.po_items pi ON pi.po_number=pb.po_number LEFT JOIN bom_database.po_landed poland ON poland.po_number=pb.po_number WHERE b.bom_status IN (55, 59, 58, 62, 63, 10) AND b.bom_archived NOT IN (1, 2) AND pb.po_number != 0 and poland.po_number is null and pi.po_number is not null  GROUP BY pb.po_number
                    """

            fetched_po_numbers = self.iom_utils.run_query(query, "SELECT")
            for po in fetched_po_numbers:
                po_number = po['po_number']

                po_items_query = f"""
                                SELECT pi.po_number, fm.poNumber, pi.cifa_item_number, fm.CIFANumber, IFNULL(IF(fm.totReceivedDisp, fm.totReceivedDisp, 0), 0) AS totReceived, pi.quantity FROM cifa.po_items pi LEFT JOIN cifa.fm_po_line fm ON fm.poNumber = pi.po_number AND fm.CIFANumber = pi.cifa_item_number WHERE pi.po_number = {po_number}
                                """

                po_items = self.iom_utils.run_query(po_items_query, "SELECT")

                if po_items and po_items[0]['po_number']:
                    self.check_po_status(po_items)
        except Exception as e:
            logger.exception(f"Exception: {e}, {traceback.format_exc()}")

