    @staticmethod
    def send_script_failure_email(log_messages, index, dashboard_url, start_time, script_id):
        try:
            from icputils.iom_utils import IomUtils
            exception_list = []
            script_name = None

            uuid = log_messages[0]["uuid"]

            for log in log_messages:
                script_name = log.get('script_name')
                level = log.get('level')
                if level and level.lower() in ('error', 'exception'):
                    exception_list.append(log)

            end_time = datetime.datetime.utcnow().strftime("%Y-%m-%dT%H:%M:%S")

            if exception_list:
                kibana_link = Kibana.get_kibana_link(uuid, index, dashboard_url, start_time, end_time, level="ERROR")
                short_script_name = script_name.split('/')[-1]
                kwargs = {
                    "kibana_link": kibana_link,
                    "script_name": short_script_name,
                    "uuid": uuid
                }
                IomUtils.send_email_from_api(**kwargs)
                Kibana.insert_failure_record(script_id, kibana_link)
            else:
                kibana_link = Kibana.get_kibana_link(uuid, index, dashboard_url, start_time, end_time)
                Kibana.insert_success_record(script_id, start_time, end_time, kibana_link)
        except Exception as e:
            logger.exception(f"Exception occurred in send_script_failure_email: {e}, {traceback.format_exc()}")

    @staticmethod
    def get_kibana_link(uuid, index, dashboard_url, start_time, end_time, level=None):
        kibana_link = None
        try:
            if level:
                search_string = f'uuid : {uuid} and level : "ERROR" '
            else:
                search_string = f'uuid : {uuid} '

            search_string = Kibana.encode_string(search_string)

            kibana_link = f"""{dashboard_url}#/?_g=(filters:!(),refreshInterval:(pause:!t,value:60000),time:(from:'{start_time}',to:'{end_time}'))&_a=(columns:!(script_name,message,level,owner,uuid),filters:!(),index:'{index}*',interval:auto,query:(language:kuery,query:'{search_string}'),sort:!(!('@timestamp',desc)))"""

        except Exception as e:
            logger.exception(f"Exception occurred in get_kibana_link: {e}, {traceback.format_exc()}")
        return kibana_link

    @staticmethod
    def search_kibana_logs(start_time, end_time, search_params):
        logs_list = []
        try:
            url, index, headers, dashboard_url = Kibana.get_config_details()
            url = f"{url}{index}/_search"

            for search_param in search_params:
                query = {
                    "bool": {
                        "filter": [
                            {
                                "range": {
                                    "@timestamp": {
                                        "gte": f"{start_time}",
                                        "lt": f"{end_time}"
                                    }
                                }
                            },
                            {
                                "wildcard": {
                                    "message": f"*{search_param}*"
                                }
                            }
                        ]
                    }
                }
                logs_list.extend(Kibana.get_pagination_data(query, url, headers))

            logs_list = [
                {
                    'id': logs_dict.get('_id'),
                    'timestamp': logs_dict.get('_source').get('@timestamp'),
                    'script_name': logs_dict.get('_source').get('script_name')
                }
                for logs_dict in logs_list
            ]
        except Exception as e:
            logger.exception(f"Exception occurred in search_kibana_logs: {e}, {traceback.format_exc()}")
        return logs_list

    @staticmethod
    def get_pagination_data(query, url, headers, size=10000):
        result = []
        try:
            payload = dumps({
                "query": query,
                "_source": True,
                "sort": [
                    {
                        "@timestamp": "asc"
                    }
                ],
                "size": size
            })

            logger.debug(f"url: {url}")
            logger.debug(f"headers: {headers}")
            logger.debug(f"payload: {payload}")

            response = request("GET", url, headers=headers, data=payload)

            if response.status_code == 200:
                total_records = response.json().get('hits', {}).get('total', {}).get('value')
                logger.debug(f"total_records: {total_records}")
                if total_records > size:
                    return Kibana.get_pagination_data(query, url, headers, size=total_records)
                result = response.json().get('hits', {}).get('hits', [])
        except Exception as e:
            logger.exception(f"Exception occurred in get_pagination_data: {e}, {traceback.format_exc()}")
        return result

    @staticmethod
    def encode_string(string):
        encoded_parts = []
        for part in string.split(" "):
            encoded_parts.append(urllib.parse.quote(part, safe=":"))
        return "%20".join(encoded_parts)

