            vcmts_wos_from_api = {}
            for gear_name, por_gear in por_gears.items():
                device_type = vcmts_wo_title_dict.get(gear_name, {}).get('device_type')
                if device_type:
                    allocation = int(por_gear.get(f'_q{quarter}_alloc'))
                    if allocation > 0:
                        months_in_quarter = {
                            1: ["January", "February", "March"],
                            2: ["April", "May", "June"],
                            3: ["July", "August", "September"],
                            4: ["October", "November", "December"]
                        }

                        quarter_months = months_in_quarter[quarter]
                        allocation_distribution = [0, 0, 0]

                        for i in range(allocation):
                            allocation_distribution[i % 3] += 1

                        month_counts = {month: count for month, count in zip(quarter_months, allocation_distribution)}
                        vcmts_wos_from_api.setdefault(year, {}).setdefault(quarter, {}).setdefault(device_type, {}).update(month_counts)

            for year, quarters in vcmts_wos_from_api.items():
                for quarter, vcmts_wos in quarters.items():
                    for gear_name, vcmts_wo in vcmts_wos.items():
                        for month, allocation in vcmts_wo.items():
                            api_count = allocation
                            db_count = vcmts_wos_from_db.get(year, {}).get(quarter, {}).get(gear_name, {}).get(month, 0)
                            difference = api_count - db_count
                            if difference > 0:
                                vcmts_wo_creation_data.setdefault(year, {}).setdefault(quarter, {}).setdefault(gear_name, {})[month] = difference

        except Exception as e:
            logger.exception(f"Exception occurred in get_vcmts_wo_creation_data: {e}")
        return vcmts_wo_creation_data

    def get_vcmts_wos_from_db(self):
        vcmts_wos_from_db = {}
        try:
            query = """
                    SELECT 
                        `year`,
                        `quarter`,
                        `month`,
                        `deviceType`,
                        COUNT(id) AS `count`
                    FROM
                        bom_database.vcmts_wo_creation_log
                    GROUP BY `year` , `quarter` , `month` , `deviceType`;
                """
            results = self.iom_utils.run_query(query, "SELECT")
            for result in results:
                vcmts_wos_from_db.setdefault(result['year'], {}).setdefault(result['quarter'], {}).setdefault(result['deviceType'], {}).setdefault(result['month'], result['count'])
        except Exception as e:
            logger.exception(f"Exception occurred in get_vcmts_wos_from_db: {e}")
        return vcmts_wos_from_db

    def create_vcmts_wos(self, vcmts_wo_creation_data):

        failure_list = []
        insert_list = []
        try:
            version = "4.0"
            for year, year_data in vcmts_wo_creation_data.items():
                for quarter, quarter_data in year_data.items():
                    for device, device_data in quarter_data.items():
                        for month, allocation in device_data.items():
                            if allocation > 0:
                                url = "https://iom.comcast.net/api/filemaker/create_vcmts_wo"
                                payload = {
                                    "WOType": "vCMTSRack",
                                    "NumOfWO": str(allocation),
                                    "StartingFrom": "1",
                                    "Type": str(device),
                                    "Version": version,
                                    "MonthName": str(month)
                                }

                                headers = {
                                    'Content-Type': 'application/json'
                                }
                                response = request("POST", url, headers=headers, data=json.dumps(payload))
                                if response.status_code == 200:
                                    wo_list = response.json().get('wo_list')
                                    if wo_list:
                                        for wo_number in wo_list:
                                            insert_list.append({
                                                "year": year,
                                                "quarter": quarter,
                                                "deviceType": device,
                                                "month": month,
                                                "woNumber": wo_number,
                                                "version": version,
                                                "team": "VCMTS"
                                            })
                                else:
                                    failure_list.append({
                                        "year": year,
                                        "quarter": quarter,
                                        "deviceType": device,
                                        "month": month,
                                        "woNumber": None,
                                        "version": version
                                    })
            if insert_list:
                self.iom_utils.insert_data(insert_list, "bom_database.rack_wo_creation_log")

        except Exception as e:
            logger.exception(f"Exception occurred in create_vcmts_wos: {e}")

        return {
            'failure_list': failure_list,
            'insert_list': insert_list
        }

