class LockWorkOrders:
    def __init__(self):
        self.iom_utils = IomUtils()
        self.lock_work_orders()

    def lock_work_orders(self):
        try:
            start_time = datetime.now()
            util.start()

            work_orders = LockWorkOrders.get_valid_work_orders()
            lock_work_orders_result = self.lock_wo(work_orders)

            end_time = datetime.now()
            self.iom_utils.calculate_run_time(start_time, end_time, "lock_work_orders", lock_work_orders_result, "lock_work_orders")
        except Exception as e:
            logger.exception(f"Exception occurred in lock_work_orders: {e}, {traceback.format_exc()}")

    @staticmethod
    def get_valid_work_orders():
        work_orders = []
        try:
            url = "https://iom.comcast.net/api/bom/wo-validation"

            payload = json.dumps({
                "action": "get-wo-validation"
            })
            headers = {
                'Content-Type': 'application/json'
            }

            response = requests.request("POST", url, headers=headers, data=payload)
            if response.status_code == 200:
                response_json = response.json()
                shipping_on_hold_dict = response_json.get('swimlane_dict', {}).get('Shipping On Hold', {}).get('Success')
                for key, value in shipping_on_hold_dict.items():
                    work_orders.append(key.split(' ')[0])
        except Exception as e:
            logger.exception(f"Exception occurred in get_valid_work_orders: {e}, {traceback.format_exc()}")
        return work_orders

    def lock_wo(self, work_orders):
        lock_work_orders_result = {}
        try:
            url = "https://iom.comcast.net/api/wo_automation/wo_lock_switch"

            for work_order in work_orders:
                payload = json.dumps({
                    "Action": "SetField",
                    "FieldName": "NetEngLock",
                    "Value": "0",
                    "WO": f"WO-{work_order}"
                })
                headers = {
                    'Content-Type': 'application/json'
                }
                response = requests.request("POST", url, headers=headers, data=payload)
                if response.status_code == 200:
                    response_json = response.json()
                    if response_json.get('status') == 1:
                        lock_work_orders_result.setdefault('Success', work_order)
                        query = f"UPDATE bom_database.wo_validation SET wo_lock = '1' WHERE wo_number = {work_order}"
                        self.iom_utils.run_query(query, "UPDATE")
                    else:
                        lock_work_orders_result.setdefault('Failed', work_orders)
                else:
                    lock_work_orders_result.setdefault('Failed', work_orders)
        except Exception as e:
            logger.exception(f"Exception occurred in lock_wo: {e}, {traceback.format_exc()}")
        return lock_work_orders_result

