class StoreLegacyLogsInMongo:
    def __init__(self):
        self.iom_utils = IomUtils()
        self.store_legacy_logs_in_mongo()

    def store_legacy_logs_in_mongo(self):
        try:
            start_time = datetime.now()
            util.start()

            insert_result = {}

            index_list = [
                # {
                #     'index': 'icp-user-hits',
                #     'collection_name': 'icp_user_hits',
                #     'date_time_field': 'log_time'
                # },
                # {
                #     'index': 'iom-user-hits',
                #     'collection_name': 'iom_user_hits',
                #     'date_time_field': 'log_time'
                # },
                # {
                #     'index': 'neteng-user-hits',
                #     'collection_name': 'neteng_user_hits',
                #     'date_time_field': 'log_time'
                # },
                {
                    'index': 'user-hits',
                    'collection_name': 'user_hits',
                    'date_time_field': 'log_time'
                }
            ]
            for index_dict in index_list:
                index = index_dict.get('index')
                collection_name = index_dict.get('collection_name')
                date_time_field = index_dict.get('date_time_field')

                collection = StoreLegacyLogsInMongo.get_collection_name(collection_name)

                recent_timestamp = self.find_most_recent_timestamp(collection, date_time_field)

                logs_list, total_records = Kibana.search_kibana_logs_v2(index, recent_timestamp, date_time_field)

                logs_list = StoreLegacyLogsInMongo.convert_logs_datetime(logs_list, index_dict)

                insert_result[f'{collection_name}_total_count'] = total_records
                insert_result[f'{collection_name}_pagination_count'] = len(logs_list)
                insert_result[f'{collection_name}_insert'] = IomUtils.insert_data_mongo(logs_list, collection, collection_name)

            end_time = datetime.now()

            logger.debug(dumps(insert_result, indent=2))

            self.iom_utils.calculate_run_time(start_time, end_time, table="store_legacy_logs_in_mongo", result=insert_result, comment="store_legacy_logs_in_mongo")
        except Exception as e:
            logger.exception(f"Exception occurred in store_legacy_logs_in_mongo: {e}, {traceback.format_exc()}")

    @staticmethod
    def convert_logs_datetime(logs_list, index_dict):
        try:
            date_time_field = index_dict['date_time_field']
            for record in logs_list:
                if date_time_field in record:
                    record[date_time_field] = datetime.fromisoformat(record[date_time_field].replace('Z', '+00:00'))
        except Exception as e:
            logger.exception(f"Exception occurred in convert_logs_datetime: {e}, {traceback.format_exc()}")
        return logs_list

    @staticmethod
    def find_most_recent_timestamp(collection, date_time_field):
        recent_timestamp = None
        try:
            if collection is not None:
                recent_document = collection.find_one(sort=[(date_time_field, -1)])
                recent_timestamp = recent_document.get(date_time_field).strftime('%Y-%m-%dT%H:%M:%S') if recent_document else None
        except Exception as e:
            logger.exception(f"Exception occurred in find_most_recent_timestamp: {e}, {traceback.format_exc()}")
        return recent_timestamp

    @staticmethod
    def get_collection_name(collection_name):
        collection = None
        try:
            mongo_client = database.mongo_con_db('analytical_mongo')
            if collection_name == 'icp_user_hits':
                collection = mongo_client.analytical.icp_user_hits
            elif collection_name == 'iom_user_hits':
                collection = mongo_client.analytical.iom_user_hits
            elif collection_name == 'neteng_user_hits':
                collection = mongo_client.analytical.neteng_user_hits
            elif collection_name == 'user_hits':
                collection = mongo_client.analytical.user_hits
        except Exception as e:
            logger.exception(f"Exception occurred in get_collection_name: {e}, {traceback.format_exc()}")
        return collection

