class PreqRemoved:
    def __init__(self, iom_utils, cifa_utils):
        self.iom_utils = iom_utils
        cifa_utils = IomUtils(db_name='cifa_db', schema_name='cifa')
        self.cifa_utils = cifa_utils
        self.cifa_api = CifaAPI(IomUtils, cifa_utils)
        self.preq_details_table = f"{self.cifa_utils.schema_name}.preq_details"
        self.preq_removed()

    def preq_removed(self):
        try:
            start_time = datetime.now()

            preq_numbers = self.get_preq_numbers()
            preq_details_request = PreqRemoved.get_preq_details_request(preq_numbers)
            self.cifa_api.count = len(preq_details_request)
            preq_details_response = IomUtils.start_thread(self.cifa_api.get_response_data, preq_details_request)
            preq_details = IomUtils.start_thread(self.cifa_api.get_preq_details, preq_details_response)
            update_result = self.update_preq_details_delete_flag(preq_details, preq_numbers)
            update_result['total_api_count'] = len(preq_details_request)

            logger.debug(dumps(update_result, indent=2))
            end_time = datetime.now()

            self.iom_utils.calculate_run_time(start_time, end_time, self.preq_details_table, update_result, 'preq_removed')
        except Exception as e:
            logger.exception(f"Exception occurred in preq_removed: {e}, {traceback.format_exc()}")

    def get_preq_numbers(self):
        preq_numbers = []
        try:
            query = f"""
                SELECT 
                    pr.preq_number
                FROM
                    {self.preq_details_table} pr
                        LEFT JOIN
                    cifa.preq_items pi ON pi.preq_number = pr.preq_number
                WHERE

                    (pr.`status` IN ('INCOMPLETE', 'IN PROCESS', 'SYSTEM_SAVED', 'REJECTED')
                        OR (delete_flag = 1
                        AND pr.`status` NOT IN ('CANCELLED')))
                        AND IFNULL(pi.po_number, 0) = 0
                GROUP BY pr.preq_number
                ORDER BY pr.creation_date DESC
                """
            results = self.cifa_utils.get_pagination_result(query)
            preq_numbers = [result.get('preq_number') for result in results]
        except Exception as e:
            logger.exception(f"Exception occurred in get_preq_numbers: {e}, {traceback.format_exc()}")
        return preq_numbers

    @staticmethod
    def get_preq_details_request(preq_numbers):
        request_data = []
        try:
            for preq_number in preq_numbers:
                request_data.append(
                    {
                        "api_name": "PREQDETAILS",
                        "data": {
                            "ReportId": CifaAPI.get_report_id('PREQDETAILS'),
                            "ParametersInput": [
                                {
                                    "Name": "REQ_NUM",
                                    "Value": f"{preq_number}"
                                },
                                {
                                    "Name": "PROJECT_NUM",
                                    "Value": ""
                                },
                                {
                                    "Name": "CREATED_BY_EMAIL_IDS",
                                    "Value": ""
                                },
                                {
                                    "Name": "REQ_DATE_FROM",
                                    "Value": ""
                                },
                                {
                                    "Name": "REQ_DATE_TO",
                                    "Value": ""
                                },
                                {
                                    "Name": "SOURCE_SYSTEM",
                                    "Value": "FileMaker"
                                }
                            ]
                        }
                    }
                )
        except Exception as e:
            logger.exception(f"Exception occurred in get_preq_details_request: {e}, {traceback.format_exc()}")
        return request_data

    def update_preq_details_delete_flag(self, preq_details, preq_numbers):
        update_result = {}
        try:
            requisition_numbers = []
            for data in preq_details:
                requisition_number = data.get('REQUISITION_HEADER', {}).get('preq_number')
                if requisition_number:
                    requisition_numbers.append(requisition_number)
            active_flag = list(set(preq_numbers) & set(requisition_numbers))
            delete_flag = list(set(preq_numbers) - set(active_flag))

            logger.debug(f"Total requisition numbers: {len(preq_numbers)}")
            logger.debug(f"Active: {len(active_flag)}")
            logger.debug(f"Delete: {len(delete_flag)}")

            query = f"""
            UPDATE {self.preq_details_table} 
            SET 
                delete_flag = 0
            WHERE
                preq_number IN (%s);
            """
            self.cifa_utils.update_query_pagination(query, active_flag, "UPDATE delete_flag to 0")

            query = f"""
            UPDATE {self.preq_details_table} 
            SET 
                delete_flag = 1
            WHERE
                preq_number IN (%s);
            """
            self.cifa_utils.update_query_pagination(query, delete_flag, "UPDATE delete_flag to 1")

            update_result['total_requisition_numbers'] = len(preq_numbers)
            update_result['active_requisition_numbers'] = len(active_flag)
            update_result['delete_requisition_numbers'] = len(delete_flag)
        except Exception as e:
            logger.exception(f"Exception occurred in update_preq_details_delete_flag: {e}, {traceback.format_exc()}")
        return update_result

