class CifaExtractByCreator:
    def __init__(self, from_date=None, to_date=None, creators=None, comment=None):
        util.start()

        self.iom_utils = IomUtils()
        self.cifa_utils = IomUtils(db_name='cifa_db', schema_name='cifa')
        self.cifa_api = CifaAPI(IomUtils, self.cifa_utils)
        self.preq_details_table = f"{self.cifa_utils.schema_name}.preq_details"
        self.preq_items_table = f"{self.cifa_utils.schema_name}.preq_items"
        self.cifa_extract_by_creator(from_date, to_date, creators, comment)

    def cifa_extract_by_creator(self, from_date, to_date, creators, comment):
        try:
            start_time = datetime.now()

            comment = comment if comment else 'cifa_extract_by_creator'
            if not from_date and not to_date and not creators:
                from_date, to_date, creators = self.get_date_and_creators()

            preq_details_request = CifaExtractByCreator.get_preq_details_request(from_date, to_date, creators)
            insert_result = self.cifa_api.insert_preq_details_and_lines(preq_details_request, self.preq_details_table, self.preq_items_table)

            logger.debug(dumps(insert_result, indent=2))
            end_time = datetime.now()

            self.iom_utils.calculate_run_time(start_time, end_time, self.preq_details_table, insert_result, comment)
            self.iom_utils.calculate_run_time(start_time, end_time, self.preq_items_table, insert_result, comment)
        except Exception as e:
            logger.exception(f"Exception occurred in cifa_extract_by_creator: {e}, {traceback.format_exc()}")

    def get_date_and_creators(self):
        from_date = to_date = None
        creators = []
        try:
            from_date, to_date = self.cifa_utils.get_date_range(from_days=1, to_days=1)

            query = f"""
                SELECT DISTINCT
                    created_by_email AS email_address
                FROM
                    cifa.preq_details
                WHERE
                    YEAR(creation_date) > 2020
            """
            results = self.cifa_utils.run_query(query, "SELECT")
            creators = [result.get('email_address') for result in results]
        except Exception as e:
            logger.exception(f"Exception occurred in get_date_and_creators: {e}, {traceback.format_exc()}")
        return from_date, to_date, creators

    @staticmethod
    def get_preq_details_request(from_date, to_date, creators):
        request_data = []
        try:
            for creator in creators:
                request_data.append(
                    {
                        "api_name": "PREQDETAILS",
                        "params": {"WSDL ": "", "WSDL": "", "WSDL%20": ""},
                        "data": {
                            "ReportId": CifaAPI.get_report_id('PREQDETAILS'),
                            "ParametersInput": [
                                {
                                    "Name": "CREATED_BY_EMAIL_IDS",
                                    "Value": creator
                                },
                                {
                                    "Name": "REQ_DATE_FROM",
                                    "Value": from_date.strftime("%Y-%m-%d")
                                },
                                {
                                    "Name": "REQ_DATE_TO",
                                    "Value": to_date.strftime("%Y-%m-%d")
                                },
                                {
                                    "Name": "SOURCE_SYSTEM",
                                    "Value": "FileMaker"
                                }
                            ]
                        }
                    }
                )
        except Exception as e:
            logger.exception(f"Exception occurred in get_preq_details_request: {e}, {traceback.format_exc()}")
        return request_data

