class PreqHistory:
    def __init__(self, iom_utils, cifa_utils, preq_details=None):
        self.iom_utils = iom_utils
        self.cifa_utils = cifa_utils
        self.preq_details = preq_details
        self.cifa_api = CifaAPI(IomUtils, cifa_utils)
        self.preq_status_history_table = f"{self.cifa_utils.schema_name}.preq_status_history"
        self.preq_history()

    def preq_history(self):
        try:
            start_time = datetime.now()

            if self.preq_details:
                comment = 'preq_history_on_demand'
                requisition_approval_history_request = PreqHistory.get_requisition_approval_history_request_on_demand(self.preq_details)
            else:
                comment = 'preq_history'
                requisition_approval_history_request = self.get_requisition_approval_history_request()

            self.cifa_api.count = len(requisition_approval_history_request)

            requisition_approval_history_response = IomUtils.start_thread(self.cifa_api.get_response_data, requisition_approval_history_request)
            self.cifa_utils.get_users_dict()
            requisition_approval_history = IomUtils.start_thread(self.cifa_api.get_requisition_approval_history_details, requisition_approval_history_response, max_workers=1)
            insert_result = self.insert_preq_status_history(requisition_approval_history)

            logger.debug(dumps(insert_result, indent=2))
            end_time = datetime.now()

            self.iom_utils.calculate_run_time(start_time, end_time, self.preq_status_history_table, insert_result, comment)
        except Exception as e:
            logger.exception(f"Exception occurred in preq_history: {e}, {traceback.format_exc()}")

    def get_requisition_approval_history_request(self):
        request_data = []
        try:
            query = f"""
             SELECT 
                    req_id, preq_number, NULL AS preq_status
                    FROM
                        cifa.preq_details pd
                    WHERE
                        ((pd.status != 'Approved'
                            AND pd.status NOT IN ('CANCELLED' , 'REJECTED', 'DELETED'))
                            OR (pd.status = 'Approved'
                            AND pd.creation_date >= DATE_ADD(CURDATE(), INTERVAL - 20 DAY)))
                            AND IFNULL(pd.delete_flag, 0) = 0 
                    UNION SELECT 
                        pd.req_id,
                        pd.preq_number,
                        MAX(IF(ph.action = 'Pending', 1, 0)) AS preq_status
                    FROM
                        cifa.preq_status_history ph
                            JOIN
                        cifa.preq_details pd ON pd.preq_number = ph.preq_number
                    WHERE
                        pd.status = 'Approved'
                        AND IFNULL(pd.delete_flag, 0) = 0 
                    GROUP BY ph.preq_number
                    HAVING preq_status = 1
            """
            results = self.cifa_utils.get_pagination_result(query)
            for result in results:
                request_data.append(
                    {
                        "api_name": "REQUISITION_APPROVAL_HISTORY",
                        "additional_data": {
                            "req_id": result.get('req_id'),
                            "preq_number": result.get('preq_number')
                        },
                        "data": {
                            "ReportId": CifaAPI.get_report_id('REQUISITION_APPROVAL_HISTORY'),
                            "ParametersInput": [
                                {
                                    "Name": "REQ_ID",
                                    "Value": result.get('req_id')
                                },
                                {
                                    "Name": "SOURCE_SYSTEM",
                                    "Value": "FILEMAKER"
                                }
                            ]
                        }
                    }
                )

        except Exception as e:
            logger.exception(f"Exception occurred in get_requisition_approval_history_request: {e}, {traceback.format_exc()}")
        return request_data

    @staticmethod
    def get_requisition_approval_history_request_on_demand(preq_details):
        request_data = []
        try:
            for preq_detail in preq_details:
                request_data.append(
                    {
                        "api_name": "REQUISITION_APPROVAL_HISTORY",
                        "additional_data": {
                            "req_id": preq_detail.get('req_id'),
                            "preq_number": preq_detail.get('preq_number')
                        },
                        "data": {
                            "ReportId": CifaAPI.get_report_id('REQUISITION_APPROVAL_HISTORY'),
                            "ParametersInput": [
                                {
                                    "Name": "REQ_ID",
                                    "Value": preq_detail.get('req_id')
                                },
                                {
                                    "Name": "SOURCE_SYSTEM",
                                    "Value": "FILEMAKER"
                                }
                            ]
                        }
                    }
                )

        except Exception as e:
            logger.exception(f"Exception occurred in get_requisition_approval_history_request: {e}, {traceback.format_exc()}")
        return request_data

    def insert_preq_status_history(self, requisition_approval_history):
        insert_result = {}
        try:
            if requisition_approval_history:
                result, duplicate_count, unique_count = self.cifa_utils.insert_data(requisition_approval_history, self.preq_status_history_table)
                if result:
                    logger.debug(f"{result} records inserted into {self.preq_status_history_table} table")
                insert_result['duplicate_count'] = duplicate_count
                insert_result['unique_count'] = unique_count
            else:
                message = f"No records found to insert into {self.preq_status_history_table} table"
                logger.debug(message)
                result = 0
                insert_result['message'] = message
            insert_result['total_records_inserted'] = result
        except Exception as e:
            logger.exception(f"Exception occurred in insert_preq_status_history: {e}, {traceback.format_exc()}")
        return insert_result

